window.NC_JOURNEYS = {"lesson-1": {"title": "Nutrition Basics", "kicker": "Read the evidence, decode the numbers, explain without overclaiming", "steps": [{"id": "l1-interactive-1", "title": "Build a nutrient map", "referenceSection": "l1-2", "teach": ["Foods supply overlapping functions: fuel, building materials and the conditions needed for body processes. Carbohydrate, protein and fat supply energy. Vitamins and minerals support important functions without providing Calories; water is also essential and supplies no energy. A nutrient needed in a small quantity is not a minor nutrient in importance.", "Essential means the body cannot make enough to meet its needs, not that larger doses are better. Sugar is a carbohydrate, but not every carbohydrate is sugar: starch contains many glucose units, while fibre resists human digestive enzymes. Classify the nutrient below by energy contribution, not by how valuable you think it is."], "type": "sort", "prompt": "Place each nutrient where it belongs in basic energy accounting.", "categories": ["Supplies energy", "No Calories"], "items": [{"label": "Protein", "category": 0, "feedback": "Protein supplies approximately 4 kcal/g as well as amino acids for many body functions."}, {"label": "Fat", "category": 0, "feedback": "Fat supplies approximately 9 kcal/g and contributes to membranes and other functions."}, {"label": "Vitamin C", "category": 1, "feedback": "Vitamin C supports processes such as collagen formation; it does not supply Calories."}, {"label": "Water", "category": 1, "feedback": "Water supports transport and reactions without contributing energy."}, {"label": "Carbohydrate", "category": 0, "feedback": "The conventional teaching factor is 4 kcal/g; labels can handle some components differently."}]}, {"id": "l1-interactive-2", "title": "Choose the right reference", "referenceSection": "l1-3", "teach": ["Nutrition numbers answer different questions. An EAR covers the estimated requirement of half a specified healthy group; an RDA aims to cover nearly all. An AI is used when evidence cannot establish an EAR and RDA. A UL is a safety boundary, not an intake target, and an EER concerns energy balance.", "A label Daily Value is a standardized comparison reference, not your client’s personal requirement. One day below an RDA does not diagnose deficiency. Before using any number in counselling, name its job, the population it describes and whether it concerns total intake or a particular source."], "type": "explore", "prompt": "Predict which number helps compare two products, then open each situation.", "panels": [{"label": "Compare two labels", "text": "Use the same serving basis and percent DV to compare contribution to a label reference. Do not call it an exact percentage of the client’s own requirement."}, {"label": "Check a supplement claim", "text": "A UL is not a target to approach. Check the nutrient, source-specific rules and total product use; individual decisions may need a pharmacist or dietitian."}, {"label": "Interpret one low-intake day", "text": "The RDA is not a diagnostic cutoff. Ask about the usual pattern, absorption, losses and clinical assessment rather than declaring a deficiency."}]}, {"id": "l1-interactive-3", "title": "Turn grams into energy", "referenceSection": "l1-5", "teach": ["A food Calorie is a kilocalorie. Basic calculations use 4 kcal per gram of carbohydrate, 4 per gram of protein and 9 per gram of fat. Multiply each nutrient separately, add the resulting energy amounts, then adjust for the amount eaten. Adding grams alone gives a mass, not an energy value.", "Serving context is essential. The values below describe the whole snack, so calculate the whole snack first. These teaching factors are approximations: real labels can differ because of rounding and other calculation conventions. Calculating energy is a numeracy exercise, not a judgement about whether a food is good or bad."], "type": "number", "prompt": "A whole snack contains 30 g carbohydrate, 10 g protein and 8 g fat. What is its total energy?", "answer": 232, "tolerance": 0, "unit": "kcal", "explanation": "30 × 4 + 10 × 4 + 8 × 9 = 120 + 40 + 72 = 232 kcal. If half were eaten, its contribution would be 116 kcal."}, {"id": "l1-interactive-4", "title": "Three percentages, three meanings", "referenceSection": "l1-7", "teach": ["Start label reading with the serving size and the amount actually eaten. Then separate grams, percent Daily Value and percent of energy. Percent energy uses nutrient Calories divided by total Calories; percent DV uses a daily label reference. They cannot be substituted for one another simply because both display a percent sign.", "AMDRs describe the whole diet’s energy distribution and vary with age. They do not require each food to match the range. Historical course labels can also differ from current labels. Explain the convention in the example rather than treating an old panel as a universal current regulatory model."], "type": "choice", "prompt": "A label gives 170 kcal and 5 g fat. Which explanation correctly describes its energy from fat?", "options": [{"label": "About 26.5%: calculate 5 × 9, then divide by 170.", "feedback": "Correct. Fat contributes 45 kcal; 45 ÷ 170 × 100 is about 26.5%. This is not the label’s percent DV.", "correct": true}, {"label": "About 2.9%: divide 5 g directly by 170 kcal.", "feedback": "This mixes grams and energy. Convert the fat grams to kcal before forming an energy ratio.", "correct": false}, {"label": "Use the printed fat percent DV; it describes the same thing.", "feedback": "Percent DV has a daily-reference denominator, not the food’s total energy. It answers a different question.", "correct": false}]}, {"id": "l1-interactive-5", "title": "What processing does—and does not—restore", "referenceSection": "l1-8", "teach": ["Enrichment commonly restores selected nutrients lost during processing. Fortification is a broader term for adding nutrients, including those not originally present in substantial amounts; the words can overlap. Refining and then enriching flour does not recreate every component of whole grain, including all of the removed fibre.", "Nutrient density concerns nutrients relative to energy; energy density concerns energy relative to weight. Neither alone describes the full value of a food or a person’s intake. A fortified food can be useful without being nutritionally identical to another food. Read the specific claim instead of letting one favourable word settle the comparison."], "type": "sort", "prompt": "Sort these statements by whether the claim is justified.", "categories": ["Supported distinction", "Overclaim"], "items": [{"label": "Adding selected vitamins does not restore everything removed in refining.", "category": 0, "feedback": "Correct: restoring selected micronutrients does not recreate the whole grain."}, {"label": "Fortified means every nutrient the body needs is present.", "category": 1, "feedback": "Fortification describes additions, not completeness."}, {"label": "A food can supply useful nutrients without much energy.", "category": 0, "feedback": "Nutrient contribution and energy contribution are different dimensions."}, {"label": "Enriched flour and whole-grain flour must be nutritionally identical.", "category": 1, "feedback": "Fibre and other components can still differ after enrichment."}]}, {"id": "l1-interactive-6", "title": "Absorption changes the story", "referenceSection": "l1-10", "teach": ["A food’s nutrient amount is not always the amount available for use. Bioavailability depends on the nutrient’s form, the food matrix, other meal components and the person’s status and health. Heme iron is generally more readily absorbed; plant foods supply nonheme iron, whose absorption responds more to the meal.", "Vitamin C can support absorption of nonheme iron, while oxalate in spinach reduces calcium absorption. Vitamins also differ: A, D, E and K are fat soluble; B vitamins and C are water soluble. Water soluble does not mean harmless at any dose, and B12 is an important exception to simple claims about limited storage."], "type": "explore", "prompt": "Predict why a nutrient label alone cannot settle these three decisions.", "panels": [{"label": "Beans with vegetables", "text": "Pairing beans with a vitamin-C-containing vegetable illustrates how meal components can support nonheme iron absorption. It is a food-planning example, not deficiency treatment."}, {"label": "Spinach versus another calcium source", "text": "A calcium amount alone misses absorption differences. Consider the food, serving and overall pattern rather than ranking sources by a single number."}, {"label": "A high-dose B-vitamin product", "text": "Water solubility does not establish safety at any dose. Review the actual ingredient and amount; excessive supplemental B6 can harm nerves."}]}, {"id": "l1-interactive-7", "title": "Observe before interpreting", "referenceSection": "l1-14", "teach": ["Nutrition assessment combines evidence rather than relying on appearance. ABCD organizes anthropometric measures, biochemical information, clinical findings and dietary history. Each contributes a different piece: a food record describes intake, while a laboratory result requires clinical interpretation. Neither automatically explains every symptom or establishes a diagnosis by itself.", "Inadequate intake can contribute to primary malnutrition; impaired digestion, absorption, use or increased losses can contribute to secondary malnutrition. Similar reported diets can therefore have different effects. A trainee can collect clear observations and identify a need for assessment without converting a possibility into a confirmed medical condition."], "type": "sort", "prompt": "Separate observations you can document from conclusions that require more evidence.", "categories": ["Observation", "Unsupported conclusion"], "items": [{"label": "The person reports skipping lunch on workdays.", "category": 0, "feedback": "This is a reported eating pattern. Explore access, appetite and scheduling before deciding why."}, {"label": "The person must be iron deficient because they feel tired.", "category": 1, "feedback": "Fatigue has multiple causes; clinical assessment is needed."}, {"label": "The food record contains no listed B12-fortified foods.", "category": 0, "feedback": "This is a record observation. Clarify completeness and supplements rather than diagnose from absence alone."}, {"label": "Body size proves that all nutrient needs are met.", "category": 1, "feedback": "Appearance cannot establish nutrient adequacy or rule out malnutrition."}]}, {"id": "l1-interactive-8", "title": "Respond to the miracle-product pitch", "referenceSection": "l1-16", "teach": ["Supplement marketing often turns a biological role into a promise: because a nutrient participates in a pathway, the product is said to improve that pathway for everyone. That leap needs evidence. An antioxidant claim or the presence of plant compounds does not establish that a pill prevents disease or replaces a varied eating pattern.", "Regulatory context also matters: rules differ by country, and a product’s marketing language is not clinical evidence for an individual benefit. A useful counselling response checks the claim, ingredients, dose and interaction concerns. It keeps the client’s goal visible while resisting both blanket reassurance and blanket dismissal."], "type": "choice", "prompt": "A client asks whether a “natural energy” vitamin can replace breakfast. What is the strongest response?", "options": [{"label": "Recommend it because vitamins help energy metabolism.", "feedback": "Helping a pathway does not mean a vitamin supplies the food energy or complete nutrition of a meal.", "correct": false}, {"label": "Reject all supplements and end the discussion.", "feedback": "Some supplements have appropriate uses. A specific review and practical food plan are more useful than dismissing the client’s question.", "correct": false}, {"label": "Clarify their goal and meal barrier; explain that vitamins do not supply Calories, then review the product and relevant safety questions.", "feedback": "Correct. You address both the misconception and the reason breakfast is missing, without pretending the product is proven or harmless.", "correct": true}]}], "practice": {"takeaway": "What this means for my practice: explain what a number can show—and what it cannot—before turning it into advice.", "ask": ["What amount does this label or record describe?", "Which reference value, age group and nutrient form are we using?", "What affects the person’s ability to obtain, eat and use food?"], "try": ["Practise one 4–4–9 calculation and explain the units aloud.", "Compare two foods on the same serving basis without labelling either morally.", "Document one observation separately from your interpretation."], "refer": ["Seek qualified assessment for suspected deficiency, malabsorption or unexplained symptoms.", "Ask a pharmacist or clinician to review high-dose supplements and interaction concerns."], "reflection": "Which nutrition number have you previously treated as more personal or diagnostic than it really is? Rewrite your explanation."}, "sources": [{"label": "Health Canada DRI definitions", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables.html"}, {"label": "National Academies guidance on individual assessment", "url": "https://www.ncbi.nlm.nih.gov/books/NBK222891/"}, {"label": "FDA guide to interpreting labels", "url": "https://www.fda.gov/food/nutrition-facts-label/how-understand-and-use-nutrition-facts-label"}, {"label": "Health Canada's macronutrient reference table", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-macronutrients.html"}, {"label": "FDA serving size guidance", "url": "https://www.fda.gov/food/nutrition-facts-label/serving-size-nutrition-facts-label"}, {"label": "FDA label changes", "url": "https://www.fda.gov/food/nutrition-food-labeling-and-critical-foods/changes-nutrition-facts-label"}, {"label": "Canadian flour requirements", "url": "https://inspection.canada.ca/en/food-labels/labelling/industry/grain-and-bakery-products/unenriched-flour"}, {"label": "FDA fortification guidance", "url": "https://www.fda.gov/media/94563/download"}, {"label": "NIH vitamin B12 fact sheet", "url": "https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/"}, {"label": "NIH vitamin B6 fact sheet", "url": "https://ods.od.nih.gov/factsheets/VitaminB6-HealthProfessional/"}, {"label": "MedlinePlus calcium overview", "url": "https://www.medlineplus.gov/ency/article/002412.htm"}, {"label": "NIH iron fact sheet", "url": "https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/"}, {"label": "NHLBI DASH evidence", "url": "https://www.nhlbi.nih.gov/health/dash/health-benefits"}, {"label": "NCCIH antioxidant evidence", "url": "https://www.nccih.nih.gov/health/antioxidant-supplements-what-you-need-to-know"}, {"label": "FDA structure and function claims", "url": "https://www.fda.gov/food/nutrition-food-labeling-and-critical-foods/structurefunction-claims"}, {"label": "Health Canada licensed natural health products database", "url": "https://www.canada.ca/en/health-canada/services/drugs-health-products/natural-non-prescription/applications-submissions/product-licensing/licensed-natural-health-products-database.html"}]}, "lesson-2": {"title": "Preconception Nutrition", "kicker": "Prepare early, distinguish dose from need, support without promising fertility", "steps": [{"id": "l2-interactive-1", "title": "Start before the positive test", "referenceSection": "l2-3", "teach": ["Preconception nutrition is preparation, not a guarantee of conception or a healthy pregnancy. Early development can precede pregnancy recognition: neural-tube closure occurs within about 28 days after conception. That timing explains why folic-acid prevention guidance begins beforehand. If pregnancy is already recognized, appropriate care now still matters; blame adds no benefit.", "Two clocks can describe the same pregnancy. Gestational age usually starts at the last menstrual period; time since conception starts later. In a simplified 28-day cycle, six weeks pregnant is roughly four weeks after fertilization. Actual ovulation varies, so calendar estimates are not a substitute for clinical dating or fertility assessment."], "type": "explore", "prompt": "Predict which preparation opportunities remain useful at each point, then compare.", "panels": [{"label": "Planning several months ahead", "text": "Establish an appropriate folic-acid routine, review medicines with the care team and investigate practical food barriers before the early developmental window."}, {"label": "Pregnancy just recognized", "text": "Encourage appropriate prenatal care now. Do not imply that missing a preconception routine makes a healthy outcome impossible."}, {"label": "Cycles are unpredictable", "text": "Avoid assuming ovulation on day 14. Menstrual concerns and fertility questions may require clinical assessment; food alone cannot explain every difficulty."}]}, {"id": "l2-interactive-2", "title": "Read the unit before the dose", "referenceSection": "l2-5", "teach": ["Folate is the general vitamin B9 term; folic acid is a form used in supplements and fortification. Canadian advice for anyone who could become pregnant includes a daily multivitamin containing 400 mcg folic acid, ideally begun at least three months before pregnancy. Folate-containing foods remain useful but do not replace this prevention advice.", "A milligram contains 1,000 micrograms. Unit conversion changes how an amount is written, not the amount itself or its chemical form. Higher-risk histories, medicines or conditions need clinician or pharmacist review rather than a trainee choosing a higher dose. Doubling a multivitamin also doubles all its other ingredients."], "type": "number", "prompt": "A label lists 0.4 mg folic acid. How many micrograms is that?", "answer": 400, "tolerance": 0, "unit": "mcg", "explanation": "0.4 × 1,000 = 400 mcg. This conversion does not turn folic acid into DFE and does not authorize a dose change."}, {"id": "l2-interactive-3", "title": "Separate three kinds of number", "referenceSection": "l2-5", "teach": ["Dietary folate equivalents account for differences in bioavailability. One mcg DFE equals one mcg naturally occurring food folate, or 0.6 mcg folic acid consumed with food. The adult folate RDA is 400 mcg DFE; the pregnancy RDA is 600 mcg DFE. These are total-intake references, not direct tablet instructions.", "A prevention supplement recommendation, a total-intake RDA and a label amount answer different questions. Do not subtract them casually as though their units and purposes were identical. An RDA is also not a toxicity threshold: exceeding it in a calculation does not by itself mean a routinely recommended prevention dose should be reduced."], "type": "sort", "prompt": "Classify the purpose of each number—not whether it is “high” or “low.”", "categories": ["Total-intake reference", "Supplement recommendation", "Unit equivalence"], "items": [{"label": "Pregnancy folate: 600 mcg DFE daily", "category": 0, "feedback": "This is the total-intake RDA expressed in dietary folate equivalents."}, {"label": "Daily multivitamin containing 400 mcg folic acid before pregnancy", "category": 1, "feedback": "This is prevention guidance for the specified group, separate from DFE accounting."}, {"label": "0.4 mg folic acid = 400 mcg folic acid", "category": 2, "feedback": "Only the metric unit changes; the nutrient form and amount do not."}, {"label": "Adult folate: 400 mcg DFE daily", "category": 0, "feedback": "This is a total-intake reference, not proof that a specific product meets prevention advice."}]}, {"id": "l2-interactive-4", "title": "A nourishing menu may still be too little", "referenceSection": "l2-4", "teach": ["Nutritional status reflects availability, intake, absorption, use, losses and stores. A menu can include vegetables, lean protein and whole grains yet provide insufficient total energy. Chronic under-fuelling can contribute to disrupted reproductive hormone signalling, but body size, exercise participation or one missed period cannot establish the cause.", "Menstrual changes deserve medical assessment because pregnancy and other conditions may need consideration. Ask about eating regularity, training changes, fatigue, stress and restrictive rules without making food responsible for every fertility concern. Respectful counselling can support adequate meals while a clinician investigates the menstrual change; these actions are complementary, not competing."], "type": "choice", "prompt": "A runner reports skipped lunches, increased training and missed periods. What comes first?", "options": [{"label": "Reassure them because the foods they do eat look healthy.", "feedback": "Food quality does not prove enough total energy, and menstrual changes should not be dismissed.", "correct": false}, {"label": "Explore food access and fuelling, and recommend medical assessment of the menstrual change.", "feedback": "Correct. You address a plausible nutritional concern while preserving investigation of other causes.", "correct": true}, {"label": "Diagnose low energy availability from the training history and prescribe a fertility calorie target.", "feedback": "The history raises a concern but does not establish the diagnosis or an individualized energy prescription.", "correct": false}]}, {"id": "l2-interactive-5", "title": "Audit the plan, not the diet label", "referenceSection": "l2-6", "teach": ["Preconception assessment looks for reliable nutrient supply, not just dietary identity. Iron supports oxygen transport; B12 supports blood-cell and neurological functions; iodine supports thyroid hormone production; choline contributes to membranes and signalling. Calcium and vitamin D have connected but distinct roles. No single food or prenatal brand proves all needs are met.", "A vegan pattern needs dependable fortified-food or supplement sources of B12. Heavy menstrual bleeding raises concern about iron depletion, but fatigue alone is not a diagnosis. Iodine in seaweed can be very high and variable, and specialty salts are not necessarily iodized. Product labels and actual frequency of use make vague descriptions more informative."], "type": "explore", "prompt": "Predict the missing information in each plan before opening the coaching note.", "panels": [{"label": "“I buy a fortified drink.”", "text": "Ask which nutrients it contains, the serving size and how often it is consumed. A carton used once a month is not evidence of a dependable daily source."}, {"label": "“My prenatal covers everything.”", "text": "Read the actual ingredients. Choline and calcium may be limited or absent; the word prenatal is not a complete nutrient assessment."}, {"label": "“Kelp will fix my thyroid.”", "text": "Do not endorse self-treatment. Variable iodine and thyroid disease warrant clinician or pharmacist review rather than an assumed benefit."}]}, {"id": "l2-interactive-6", "title": "Keep the fish category and time window", "referenceSection": "l2-7", "teach": ["Fish advice balances nutrient benefits with mercury exposure; it does not mean avoiding all fish. For people who are or may become pregnant, Canadian guidance limits the combined listed higher-mercury fish—including fresh or frozen tuna, shark and swordfish—to 150 g per month. Canned albacore has a separate 300 g per week limit.", "The species, product and time period are essential parts of the advice. Canned light tuna is not the same category as albacore, and salmon is not added to that specified higher-mercury total. Local catch advisories can add context. Practise the accounting before explaining substitutions that fit the person’s preferences and access."], "type": "number", "prompt": "Two 90 g portions of fish from the listed higher-mercury group are eaten in one month. What is their combined amount?", "answer": 180, "tolerance": 0, "unit": "g", "explanation": "90 + 90 = 180 g in that month, above the specified 150 g/month combined limit. This is not a limit for all fish."}, {"id": "l2-interactive-7", "title": "Support the goal, refer the condition", "referenceSection": "l2-8", "teach": ["Medical conditions and medicines can change preparation needs. Established diabetes calls for a clinician-led preconception plan; a multivitamin does not replace glucose management or medication review. PCOS does not imply one universally superior diet or justify telling everyone to eliminate carbohydrate. Sustainable, individualized support is preferable to a promised fertility cure.", "A nutrition trainee can help identify meal barriers, collect an accurate supplement list and support the agreed clinical plan. Diagnosis, treatment-dose selection and stopping medicines are different responsibilities. Ask permission before discussing weight and focus on behaviours and access without implying that pregnancy success depends on body size or perfect eating."], "type": "sort", "prompt": "Sort these next steps by whether they fit routine trainee support or require clinical decision-making.", "categories": ["Support within trainee scope", "Clinical decision needed"], "items": [{"label": "Ask when work shifts make meals difficult.", "category": 0, "feedback": "Understanding access and routines can make general food support feasible."}, {"label": "Select a higher folic-acid dose after a previous neural-tube-defect-affected pregnancy.", "category": 1, "feedback": "That history warrants individualized clinician or pharmacist assessment."}, {"label": "Record all supplements and their label amounts for review.", "category": 0, "feedback": "Accurate information supports safer professional review without prescribing."}, {"label": "Stop a prescribed medicine because pregnancy is planned.", "category": 1, "feedback": "Medicine benefits and risks need a prescriber or pharmacist; do not direct independent discontinuation."}]}, {"id": "l2-interactive-8", "title": "Make the first action repeatable", "referenceSection": "l2-7", "teach": ["A feasible eating pattern uses foods the person enjoys and can obtain. Combining a carbohydrate food, protein, produce and suitable fat is a flexible planning aid, not a rule that every meal must look the same. Cultural staples do not need to be replaced by expensive products marketed for fertility.", "Ask about food running out, equipment, storage, shift schedules and symptoms before suggesting recipes. Someone who skips lunch may need accessible food rather than another nutrition lecture. Agree on one action the person would actually repeat and check whether it helps. Better nutrient intake supports health but should never be presented as a promise of conception."], "type": "choice", "prompt": "A client has little money, no refrigerator at work and no midday meal. Which opening is most useful?", "options": [{"label": "Ask what shelf-stable foods they enjoy and can afford, then plan one realistic lunch option together.", "feedback": "Correct. The action responds to the actual constraint and invites the client’s preferences.", "correct": true}, {"label": "Recommend organic fertility smoothies and a strict meal schedule.", "feedback": "This ignores cost and storage and adds an unsupported fertility promise.", "correct": false}, {"label": "Remove rice from dinner before discussing lunch.", "feedback": "The immediate gap is a missing meal. Removing a familiar staple does not address that barrier.", "correct": false}]}], "practice": {"takeaway": "What this means for my practice: prepare early without promising fertility, and keep nutrient form, total need and supplement advice separate.", "ask": ["Could pregnancy occur, and what preparation or care is already in place?", "Which foods, fortified products, supplements and medicines are actually used—and how often?", "What makes regular, sufficient eating difficult?"], "try": ["Practise explaining 0.4 mg versus 400 mcg without confusing either with DFE.", "Build one accessible meal option using familiar foods.", "Help prepare a complete product list for a clinician or pharmacist review."], "refer": ["Refer menstrual changes, fertility concerns, diabetes and thyroid concerns for appropriate clinical assessment.", "Refer higher-risk folate histories or requests for treatment-dose supplements rather than selecting doses."], "reflection": "How would you support someone who has just discovered a pregnancy without implying they failed by not preparing earlier?"}, "sources": [{"label": "ASRM: optimizing natural fertility", "url": "https://www.asrm.org/practice-guidance/practice-committee-documents/optimizing-natural-fertility-a-committee-opinion-2021/"}, {"label": "ACOG: fetal development", "url": "https://www.acog.org/womens-health/faqs/how-your-fetus-grows-during-pregnancy"}, {"label": "UCSF: conception", "url": "https://www.ucsfhealth.org/health-articles/conception-how-it-works"}, {"label": "NIH ODS: pregnancy", "url": "https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"}, {"label": "PHAC: folic acid and neural tube defects", "url": "https://www.canada.ca/en/public-health/services/pregnancy/folic-acid.html"}, {"label": "Endocrine Society: hypothalamic amenorrhea guideline", "url": "https://www.endocrine.org/clinical-practice-guidelines/hypothalamic-amenorrhea"}, {"label": "ASRM: evaluation of amenorrhea", "url": "https://www.asrm.org/practice-guidance/practice-committee-documents/current-evaluation-of-amenorrhea/"}, {"label": "NIH ODS: folate", "url": "https://ods.od.nih.gov/factsheets/Folate-HealthProfessional/"}, {"label": "Health Canada: mineral reference values", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-elements.html"}, {"label": "Health Canada: vitamin reference values", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-vitamins.html"}, {"label": "NIH ODS: iron", "url": "https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/"}, {"label": "Health Canada: pregnancy nutrition", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/applying/advice-nutrition-different-life-stages/considerations-pregnancy-support-breastfeeding.html"}, {"label": "NIH ODS: vitamin B12", "url": "https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/"}, {"label": "NIH ODS: iodine", "url": "https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/"}, {"label": "NIH ODS: choline", "url": "https://ods.od.nih.gov/factsheets/Choline-HealthProfessional/"}, {"label": "Health Canada: vitamin D", "url": "https://www.canada.ca/en/health-canada/services/nutrients/vitamin-d.html"}, {"label": "Health Canada: healthy eating on a budget", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}, {"label": "Health Canada: mercury in fish", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/food-safety/chemical-contaminants/environmental-contaminants/mercury/mercury-fish.html"}, {"label": "NIDDK: pregnancy with diabetes", "url": "https://www.niddk.nih.gov/health-information/diabetes/diabetes-pregnancy"}, {"label": "2023 international PCOS guideline", "url": "https://www.monash.edu/__data/assets/pdf_file/0003/3379521/Evidence-Based-Guidelines-2023.pdf"}, {"label": "CDC: planning for pregnancy", "url": "https://www.cdc.gov/pregnancy/about/index.html"}]}, "lesson-3": {"title": "Pregnancy Nutrition", "kicker": "Connect the physiology to practical support—and know when to stop coaching", "steps": [{"id": "l3-interactive-1", "title": "Three clocks, three different questions", "referenceSection": "l3-2", "teach": ["Pregnancy nutrition changes over time, but early and later needs both matter. Gestational age normally begins at the last menstrual period; conception age starts later. In the simplified cycle model, the clocks differ by about two weeks. Neural-tube development occurs early, which explains preconception folic-acid advice without making later care unimportant.", "Outcome terms also need context. Preterm means before 37 completed gestational weeks; low birth weight means under 2,500 g regardless of gestational age. Small for gestational age concerns size relative to gestational age. A comparison without its clock or denominator can sound precise while answering the wrong question."], "type": "explore", "prompt": "Predict why these descriptions cannot be substituted for one another.", "panels": [{"label": "Six weeks pregnant", "text": "In the familiar cycle model this is about four weeks after fertilization, not six. Clinical dating can differ from a calendar estimate."}, {"label": "An infant born before 37 weeks", "text": "This describes prematurity. It does not alone establish whether weight is appropriate for gestational age."}, {"label": "An infant weighing under 2,500 g", "text": "This describes low birth weight. It does not tell you whether the infant was preterm or born at term."}]}, {"id": "l3-interactive-2", "title": "The placenta is not a protective wall", "referenceSection": "l3-3", "teach": ["The placenta supports nutrient and oxygen exchange, fetal waste removal and hormone production. Maternal and fetal circulations normally remain physically separate while substances cross the interface through different processes. Maternal intake is not translated one-for-one into fetal exposure, and neither “everything crosses” nor “nothing harmful crosses” describes the system accurately.", "Maternal glucose can cross; maternal insulin does not cross in clinically significant amounts in ordinary circumstances. The fetus makes its own insulin in response to glucose exposure. Alcohol and some medicines can cross, so the placenta is not a safety guarantee. Medicine changes belong with the prescriber or pharmacist, not a blanket instruction to stop treatment."], "type": "sort", "prompt": "Sort each explanation into a supported mechanism or a misleading shortcut.", "categories": ["Supported mechanism", "Misleading shortcut"], "items": [{"label": "The placenta helps exchange nutrients and gases.", "category": 0, "feedback": "Exchange is one of its major roles, alongside endocrine functions and waste transfer."}, {"label": "Maternal insulin crosses to control fetal glucose.", "category": 1, "feedback": "The key mechanism is maternal glucose exposure prompting fetal insulin production."}, {"label": "The placenta guarantees medication safety.", "category": 1, "feedback": "Transfer varies and some exposures can affect development; professional medicine review is needed."}, {"label": "The fetus produces its own insulin.", "category": 0, "feedback": "This distinction explains the maternal-glucose to fetal-insulin pathway."}]}, {"id": "l3-interactive-3", "title": "Concentration is not the whole story", "referenceSection": "l3-4", "teach": ["Pregnancy expands blood volume. Plasma volume increases proportionally more than red-cell volume, so a concentration can fall even when the total amount in circulation rises. Picture adding some beads and much more water to a jar: there are more beads overall, but fewer per spoonful. This is a useful analogy for haemodilution.", "That mechanism neither proves nor rules out iron deficiency. Pregnancy-related lipid and glucose adaptations also differ, so “everything gets diluted” is not a reliable rule. A counsellor can explain why context matters while directing laboratory interpretation to the prenatal team. Reassurance must not become dismissal, and uncertainty must not become an automatic high-dose prescription."], "type": "choice", "prompt": "A client says, “My haemoglobin fell, so I must be eating badly.” What is the best explanation?", "options": [{"label": "It is always normal dilution, so ignore the result.", "feedback": "Dilution does not exclude iron deficiency or other clinical concerns.", "correct": false}, {"label": "Any fall proves deficiency, so immediately double the prenatal.", "feedback": "A concentration change alone is insufficient, and doubling a prenatal increases every ingredient.", "correct": false}, {"label": "Plasma expansion can lower concentration, but iron deficiency can coexist; the prenatal team should interpret the result.", "feedback": "Correct. This explains physiology, avoids blame and preserves necessary assessment.", "correct": true}]}, {"id": "l3-interactive-4", "title": "Add intake without prescribing a menu", "referenceSection": "l3-5", "teach": ["Pregnancy needs additional nourishment, not automatic doubling of meals. Health Canada describes a small increase in nutritious food during the second and third trimesters, adapted to circumstances. The familiar protein reference is 71 g daily; it is not a universal maximum or a compulsory supplement dose for every pregnant person.", "Other pregnancy references include 175 g carbohydrate, 28 g fibre and 3.0 L total water daily. Total water includes food and beverages, not three litres of extra plain water. Calculating food contributions helps interpret a record, but does not establish absorption, adequacy in every circumstance or a treatment plan for vomiting, diabetes or kidney disease."], "type": "number", "prompt": "An illustrative day supplies 15 g protein at breakfast, 23 g at lunch, 25 g at dinner and 10 g in snacks. What is the total?", "answer": 73, "tolerance": 0, "unit": "g protein", "explanation": "15 + 23 + 25 + 10 = 73 g. This is an intake estimate, not proof of individual adequacy or a prescribed menu."}, {"id": "l3-interactive-5", "title": "Prenatal numbers need their labels", "referenceSection": "l3-7", "teach": ["Pregnancy increases micronutrient needs, but total-intake references are not the same as supplement recommendations. Folate has a 600 mcg DFE total RDA; Canadian advice separately includes a prenatal containing 400 mcg folic acid. Iron has a 27 mg total RDA, while routine Canadian prenatal advice specifies 16–20 mg in the daily multivitamin.", "Foods still contribute, and the prenatal’s name does not guarantee substantial calcium or choline. High-dose preformed vitamin A can be harmful; “natural” does not establish safety. For twins, do not automatically double the product. Additional needs, adverse effects or treatment questions require individualized review rather than simple multiplication."], "type": "sort", "prompt": "Identify what each figure actually describes.", "categories": ["Total-intake reference", "Routine supplement guidance", "Unsafe shortcut"], "items": [{"label": "27 mg iron daily in pregnancy", "category": 0, "feedback": "This is the pregnancy total-intake RDA, not an automatic tablet dose."}, {"label": "16–20 mg iron in a daily prenatal under Canadian guidance", "category": 1, "feedback": "This describes routine supplementation; treatment needs can differ."}, {"label": "600 mcg DFE folate daily", "category": 0, "feedback": "This is a total folate reference expressed in DFE, not 600 mcg folic acid."}, {"label": "Double every prenatal ingredient for twins", "category": 2, "feedback": "Multiple pregnancy needs individual review; doubling also increases ingredients that may become excessive."}]}, {"id": "l3-interactive-6", "title": "Make food advice usable and safe", "referenceSection": "l3-11", "teach": ["Nausea, reflux and constipation can make a perfect-looking meal plan unusable. Small amounts of tolerated foods, practical help with cooking and individual adjustments may be more useful than a long forbidden-food list. Persistent vomiting, inability to keep fluids down, reduced urine or faintness calls for clinical assessment rather than escalating nutrition instructions.", "Food safety and exposure advice also require specifics. Fish recommendations distinguish species and time periods rather than banning all fish. Organic does not mean sterile, and an appealing label does not replace safe handling. Ask what is feasible, identify risk first, and choose an achievable change without making symptoms the person’s fault."], "type": "explore", "prompt": "Predict which barrier needs adaptation and which needs clinical care.", "panels": [{"label": "Cooking smells trigger nausea", "text": "Explore tolerated cold foods and practical preparation help. The goal is usable nourishment, not forcing a hot breakfast that worsens symptoms."}, {"label": "Fluids cannot be kept down", "text": "Prompt clinical assessment takes priority, especially with little urine, dizziness or fainting. A new recipe is not sufficient."}, {"label": "Constipation began with a supplement", "text": "Discuss symptoms and the product with the prenatal clinician or pharmacist. Do not silently stop the whole prenatal or prescribe a new treatment."}]}, {"id": "l3-interactive-7", "title": "Weight-gain arithmetic has limits", "referenceSection": "l3-10", "teach": ["Pregnancy gain includes fetal and placental tissues, fluid and maternal changes; it is not simply stored body fat. Guidance depends on pre-pregnancy measurements and whether the pregnancy is singleton or multiple. BMI uses weight in kilograms divided by height in metres squared; premature rounding can move a result across a category boundary.", "These references support clinical assessment, not judgements about effort or worth. Ask permission before discussing weight and keep symptoms, intake and growth monitoring in view. A fixed calories-per-pound shortcut cannot establish an appropriate pregnancy-wide energy prescription. Multiple pregnancy especially requires individualized planning rather than multiplying a singleton menu or supplement list."], "type": "choice", "prompt": "Someone carrying twins asks for a calorie total obtained by multiplying planned pounds gained by 3,500. How should you respond?", "options": [{"label": "Double a standard singleton intake and every supplement instead.", "feedback": "Neither food nor supplement needs safely reduce to doubling; review and monitoring matter.", "correct": false}, {"label": "Explain why pregnancy gain is not just fat storage and coordinate individualized food planning with the maternity team.", "feedback": "Correct. The proposed shortcut ignores the composition of gain and changing clinical needs.", "correct": true}, {"label": "Use the shortcut because all weight gain has the same energy cost.", "feedback": "Pregnancy gain contains different tissues and fluid; this assumption is not justified.", "correct": false}]}, {"id": "l3-interactive-8", "title": "Recognize the moment to stop meal planning", "referenceSection": "l3-12", "teach": ["Preeclampsia is a multisystem pregnancy disorder, not simply a nutrition problem. Persistent severe headache, visual disturbance, upper-abdominal pain or difficulty breathing requires urgent maternity assessment. A counsellor does not need to prove the diagnosis before recommending urgent help. A seizure or severe breathing difficulty warrants emergency services.", "Diabetes in pregnancy likewise needs clinical testing and coordinated care. Maternal glucose exposure can increase fetal insulin production; this is a risk pathway, not a prediction or basis for blame. Eliminating all carbohydrates or relying on a supplement does not replace the diabetes team’s plan. Safety concerns always outrank completing a food worksheet."], "type": "choice", "prompt": "During a meal-planning session a pregnant client reports a severe headache and blurred vision. What is the priority?", "options": [{"label": "Pause the nutrition exercise and arrange urgent maternity assessment.", "feedback": "Correct. Potentially serious symptoms require timely clinical assessment, not proof of a diagnosis from you.", "correct": true}, {"label": "Finish the food diary first to identify a dietary trigger.", "feedback": "A diary must not delay assessment of concerning pregnancy symptoms.", "correct": false}, {"label": "Recommend high-dose iron to prevent preeclampsia.", "feedback": "High-dose iron is not a preeclampsia-prevention strategy and cannot replace urgent care.", "correct": false}]}], "practice": {"takeaway": "What this means for my practice: connect an explanation to one feasible action, but let clinical risk—not the lesson plan—set the priority.", "ask": ["What symptoms, prenatal monitoring and clinician instructions are relevant today?", "Which foods and fluids are currently tolerated and accessible?", "What do the actual prenatal and other product labels contain?"], "try": ["Explain one pregnancy mechanism without blaming the client.", "Build one small, tolerated meal or snack adaptation using familiar foods.", "Separate a total-intake reference from a supplement amount in your notes."], "refer": ["Escalate severe headache, visual change, breathing difficulty or other concerning acute symptoms urgently.", "Coordinate diabetes, abnormal laboratory findings, severe vomiting or multifetal nutrition concerns with the maternity team."], "reflection": "What would make you pause an otherwise useful nutrition session, and what exact action would you take next?"}, "sources": [{"label": "PHAC: neural-tube timing", "url": "https://www.canada.ca/en/public-health/services/publications/healthy-living/maternity-newborn-care-guidelines-chapter-2.html"}, {"label": "PHAC: folic acid", "url": "https://www.canada.ca/en/public-health/services/pregnancy/folic-acid.html"}, {"label": "WHO: preterm birth", "url": "https://www.who.int/news-room/fact-sheets/detail/preterm-birth"}, {"label": "WHO: low birth weight", "url": "https://www.who.int/data/nutrition/nlis/info/low-birth-weight"}, {"label": "NICHD: placenta functions", "url": "https://www.nichd.nih.gov/newsroom/digital-media/infographics/placenta-textalt"}, {"label": "Diabetes Canada: diabetes and pregnancy", "url": "https://www.diabetes.ca/for-professionals/full-guidelines/chapter-36"}, {"label": "PHAC: care during pregnancy", "url": "https://www.canada.ca/en/public-health/services/publications/healthy-living/maternity-newborn-care-guidelines-chapter-3.html"}, {"label": "NCBI: physiology of pregnancy", "url": "https://www.ncbi.nlm.nih.gov/books/NBK559304/"}, {"label": "Health Canada: pregnancy nutrition", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/applying/advice-nutrition-different-life-stages/considerations-pregnancy-support-breastfeeding.html"}, {"label": "Health Canada: macronutrient reference values", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-macronutrients.html"}, {"label": "Health Canada: vitamin reference values", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-vitamins.html"}, {"label": "NIH: folate and DFE", "url": "https://ods.od.nih.gov/factsheets/Folate-HealthProfessional/"}, {"label": "Health Canada: mineral reference values", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-elements.html"}, {"label": "NIH: iron", "url": "https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/"}, {"label": "NIH: pregnancy dietary supplements", "url": "https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"}, {"label": "Health Canada: mercury in fish", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/food-safety/chemical-contaminants/environmental-contaminants/mercury/mercury-fish.html"}, {"label": "Health Canada: caffeine", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/food-safety/food-additives/caffeine-foods.html"}, {"label": "CDC: alcohol during pregnancy", "url": "https://www.cdc.gov/alcohol-pregnancy/about/"}, {"label": "Health Canada: safe grocery handling", "url": "https://www.canada.ca/en/health-canada/services/general-food-safety-tips/safe-food-handling-practices-grocery-store.html"}, {"label": "Health Canada: gestational weight-gain guidelines", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/healthy-weights/prenatal-guidelines-professionals-gestational-weight-gain.html"}, {"label": "CDC: singleton weight-gain guidance", "url": "https://www.cdc.gov/maternal-infant-health/pregnancy-weight/index.html"}, {"label": "ACOG: nausea and vomiting", "url": "https://www.acog.org/womens-health/faqs/morning-sickness-nausea-and-vomiting-of-pregnancy"}, {"label": "PHAC: healthy pregnancy guide", "url": "https://www.canada.ca/en/public-health/services/health-promotion/healthy-pregnancy/healthy-pregnancy-guide.html"}, {"label": "Association of Ontario Midwives: pregnancy hypertension thresholds", "url": "https://www.ontariomidwives.ca/sites/default/files/2023-05/CPG-HDP-2023-PUB.pdf"}, {"label": "NICE: hypertension in pregnancy recommendations", "url": "https://www.nice.org.uk/guidance/ng133/chapter/recommendations"}, {"label": "ACOG: preeclampsia", "url": "https://www.acog.org/womens-health/faqs/preeclampsia-and-high-blood-pressure-during-pregnancy"}, {"label": "WHO: preeclampsia prevention", "url": "https://www.who.int/news-room/fact-sheets/detail/pre-eclampsia"}, {"label": "ADA: effects of gestational diabetes on the baby", "url": "https://diabetes.org/living-with-diabetes/pregnancy/gestational-diabetes/how-will-this-impact-my-baby"}, {"label": "ADA: Standards of Care 2026, diabetes in pregnancy", "url": "https://doi.org/10.2337/dc26-s015"}, {"label": "Alberta Health Services: diabetes in pregnancy nutrition guideline", "url": "https://www.albertahealthservices.ca/assets/info/nutrition/if-nfs-ng-diabetes-in-pregnancy.pdf"}, {"label": "ACOG: multiple-pregnancy risks", "url": "https://www.acog.org/womens-health/faqs/multiple-pregnancy"}, {"label": "Alberta Health Services: pregnancy with multiples", "url": "https://www.albertahealthservices.ca/assets/info/nutrition/if-nfs-ng-pregnancy-multiples.pdf"}]}, "lesson-4": {"title": "Lactation Nutrition", "kicker": "Two people, two labels, one respectful support plan", "steps": [{"id": "l4-interactive-1", "title": "Begin with the family’s goal", "referenceSection": "l4-2", "teach": ["Lactation counselling concerns both the person producing milk and the infant receiving it. Ask about recovery, food access, feeding goals and wellbeing alongside infant feeding and growth follow-up. Population breastfeeding recommendations support health; they are not a test of parental worth or a reason to withhold support from a different feeding pathway.", "Families may breastfeed, express milk, combine methods or use commercial formula. Respectful questions uncover pain, work constraints, medical issues and preferences more effectively than assumptions do. One person’s needs should not disappear behind the other’s. Begin by understanding the goal and checking safety before deciding which information would actually help today."], "type": "choice", "prompt": "A parent uses both breastmilk and formula. Which opening best supports useful counselling?", "options": [{"label": "“Why haven’t you returned to exclusive breastfeeding?”", "feedback": "This assumes a goal and can obscure pain, constraints or an informed preference.", "correct": false}, {"label": "“Mixed feeding means we no longer need to discuss lactation nutrition.”", "feedback": "The lactating parent and partially breastfed infant still have relevant nutritional and safety needs.", "correct": false}, {"label": "“How is feeding going for you, and what would you like help with?”", "feedback": "Correct. This invites the family’s goals while leaving room to assess feeding safety and practical needs.", "correct": true}]}, {"id": "l4-interactive-2", "title": "Production, transfer and intake are different", "referenceSection": "l4-3", "teach": ["Milk is produced in mammary alveoli. Prolactin supports production; oxytocin supports milk ejection by causing contractions that move milk toward the nipple. Effective milk removal and local regulation help maintain ongoing supply. This physiology is not a willpower contest and cannot be reduced to eating one special ingredient.", "Separate production, transfer and infant intake. Milk may be present but not transferred effectively, and one pumping session does not measure everything an infant receives. Concerns need feeding history and qualified assessment. Better parent nourishment is valuable, but promising that a snack or tea will correct a transfer problem confuses different parts of the system."], "type": "explore", "prompt": "Predict what each observation can—and cannot—tell you.", "panels": [{"label": "A small pumping volume", "text": "This single session is not a complete measure of supply or infant intake. Explore the context and qualified feeding assessment if concerns persist."}, {"label": "A parent skips meals", "text": "This identifies a nourishment and support issue. Practical food help matters but does not prove the cause of a feeding problem."}, {"label": "Painful feeds and growth concerns", "text": "Prompt feeding and medical assessment is appropriate. Do not substitute a milk-boosting recipe for investigation of transfer and infant wellbeing."}]}, {"id": "l4-interactive-3", "title": "Feed the parent without a miracle claim", "referenceSection": "l4-4", "teach": ["Lactation usually calls for a small amount of additional food. A snack or small meal can help meet greater needs, and keeping water available supports drinking to thirst. The amount needed varies with milk production, body size, activity and the rest of the diet; a compulsory calorie count is not the only way to offer useful support.", "Practical arrangements can matter more than a long nutrient lecture: a prepared lunch, accessible snacks or help with shopping may address the real barrier. Foods such as yogurt with oats, hummus and bread, or a bean-and-rice bowl can be workable options. None should be promoted as a guaranteed milk booster."], "type": "sort", "prompt": "Sort each suggestion by whether it supports nourishment or makes an unsupported promise.", "categories": ["Practical nourishment support", "Unsupported promise"], "items": [{"label": "Ask a support person to prepare tomorrow’s lunch.", "category": 0, "feedback": "This addresses time and food access without claiming to treat a supply problem."}, {"label": "A special cookie guarantees more milk.", "category": 1, "feedback": "A food cannot be promised to fix production or transfer problems."}, {"label": "Keep water within reach and respond to thirst.", "category": 0, "feedback": "Accessible fluids are a practical support rather than a forced-fluid treatment."}, {"label": "A stronger herbal tea will correct poor infant intake.", "category": 1, "feedback": "Poor intake needs appropriate assessment; product evidence, safety and interactions also require review."}]}, {"id": "l4-interactive-4", "title": "The same amount, written two ways", "referenceSection": "l4-4", "teach": ["Canadian postpartum guidance recommends a daily multivitamin containing 0.4 mg folic acid during breastfeeding. This supplement amount is different from the adult lactation folate RDA of 500 mcg DFE total intake. The first describes folic acid in a product; the second uses dietary folate equivalents to account for nutrient forms.", "A metric conversion does not change the nutrient form or establish total intake. Keep the label amount, daily frequency and food sources separate when recording a plan. This simple habit makes duplicate products easier to identify and helps you explain why apparently different numbers may describe different things rather than contradictory advice."], "type": "number", "prompt": "Convert 0.4 mg folic acid into micrograms.", "answer": 400, "tolerance": 0, "unit": "mcg", "explanation": "0.4 × 1,000 = 400 mcg folic acid. It is not the same statement as 500 mcg DFE total folate intake."}, {"id": "l4-interactive-5", "title": "A lower reference is not a stop-treatment order", "referenceSection": "l4-5", "teach": ["For lactation at ages 19–50, total daily references include 9 mg iron, 1,000 mg calcium, 2.8 mcg B12, 290 mcg iodine and 550 mg choline; choline uses an AI rather than an RDA. These figures describe population intake references, not automatic tablet doses or proof that a postpartum person’s stores are adequate.", "Birth-related blood loss or diagnosed anaemia may require a clinical treatment plan even though the lactation iron RDA is lower than pregnancy’s. Reliable B12 matters for parent and infant, and iodine excess can also cause harm. Review actual sources and labels rather than assuming that a postnatal product is complete or that a lower reference means stopping treatment."], "type": "explore", "prompt": "Predict which assumption needs correcting before opening each review.", "panels": [{"label": "“The iron RDA fell, so I stopped prescribed iron.”", "text": "A population reference does not override treatment for blood loss or anaemia. Ask the prescribing clinician about the plan."}, {"label": "“My vegan diet has fermented foods, so B12 is covered.”", "text": "Review dependable fortified-food or supplement sources. Suspected parent or infant deficiency needs timely assessment; treating only the parent may not be enough."}, {"label": "“A kelp supplement easily supplies iodine.”", "text": "Kelp amounts can be unpredictable. Review thyroid history, food sources and all product labels with a qualified professional rather than casually adding iodine."}]}, {"id": "l4-interactive-6", "title": "Two people, two vitamin D records", "referenceSection": "l4-7", "teach": ["The lactating adult’s vitamin D RDA is 600 IU daily total intake. Canadian food guidance also describes vitamin-D-containing foods or a 400 IU supplement; existing multivitamin content matters. These statements concern the adult and answer different questions about total need and practical supplementation.", "A breastfed or partially breastfed infant needs 400 IU vitamin D daily under Canadian guidance. Routine maternal supplementation does not replace that infant dose. Fully formula-fed infants do not routinely need additional vitamin D under the same guidance, though individual medical advice can differ. Check infant product concentration carefully: one drop is not interchangeable with one millilitre."], "type": "choice", "prompt": "A mixed-feeding parent stopped infant drops because their own prenatal contains vitamin D. What is the best response?", "options": [{"label": "Tell them to use one millilitre of any infant product.", "feedback": "Concentrations vary. The amount must be checked against the specific product, not guessed.", "correct": false}, {"label": "Explain the separate infant recommendation and confirm the infant product and measuring method with the caregiver or pharmacist.", "feedback": "Correct. Mixed feeding and routine parent supplementation do not replace the infant recommendation.", "correct": true}, {"label": "Reassure them that vitamin D in the prenatal automatically covers the infant.", "feedback": "Routine parent supplementation does not substitute for the breastfed infant’s own recommended dose.", "correct": false}]}, {"id": "l4-interactive-7", "title": "Restrictions and products need a reason", "referenceSection": "l4-8", "teach": ["There is no routine need to remove major food groups from the parent’s diet solely to prevent infant allergy. An unsettled evening after a meal does not establish causation. Ask what happened and whether there are concerning symptoms; suspected reactions warrant assessment rather than an increasingly restricted maternal diet.", "Fish advice remains category-specific, and Health Canada’s breastfeeding caffeine maximum is 300 mg daily from all sources—a ceiling, not a target. Avoiding alcohol is safest. Herbal lactation products also need ingredient, evidence and interaction review. A natural label or personal testimonial does not establish safety or show that the product addresses the actual feeding concern."], "type": "sort", "prompt": "Sort these responses into careful reasoning or a shortcut that overclaims.", "categories": ["Careful reasoning", "Overclaim"], "items": [{"label": "Ask about the symptoms before removing several food groups.", "category": 0, "feedback": "This preserves useful observation and avoids unsupported broad restriction."}, {"label": "Treat every unsettled evening as proof of a food allergy.", "category": 1, "feedback": "Timing alone does not establish a diagnosis."}, {"label": "Count caffeine across drinks, foods and products.", "category": 0, "feedback": "The daily maximum concerns all sources, not only coffee."}, {"label": "Assume an herbal supply product is harmless because it is natural.", "category": 1, "feedback": "Ingredients, dose consistency, evidence and interactions still matter."}]}, {"id": "l4-interactive-8", "title": "Safety before supply coaching", "referenceSection": "l4-10", "teach": ["Persistent pain, suspected poor transfer or growth concerns warrant prompt feeding and medical assessment. An infant who is unusually sleepy, feeding poorly or producing markedly less urine needs urgent medical assessment now, not a trial of snacks or teas. Dehydration concerns and acute illness outrank the completion of an educational activity.", "The parent also needs attention: a hot, painful, swollen breast with fever or flu-like symptoms deserves clinical advice, especially if worsening. A nutrition counsellor should not diagnose the cause, prescribe antibiotics or recommend aggressive massage or excessive pumping. Record observations and advice respectfully, distinguishing reported symptoms from a confirmed diagnosis."], "type": "choice", "prompt": "A hungry parent asks for a stronger supply tea and says the infant is sleepier, feeding poorly and urinating less. What takes priority?", "options": [{"label": "Arrange urgent medical assessment now for the infant while addressing parent support and feeding review.", "feedback": "Correct. The infant’s symptoms require urgent medical assessment now; nutrition and lactation support remain useful but must not delay care.", "correct": true}, {"label": "Try an extra snack and reassess in a week.", "feedback": "Meal support is valuable, but these infant symptoms require urgent medical assessment now rather than a delayed experiment.", "correct": false}, {"label": "Recommend a higher herbal dose because the current tea failed.", "feedback": "The problem has not been assessed, and neither effectiveness nor safety of a higher dose is established.", "correct": false}]}], "practice": {"takeaway": "What this means for my practice: support both parent and infant without treating food, feeding mechanics and clinical care as interchangeable.", "ask": ["What feeding goals and difficulties matter most to you today?", "How are infant feeding, urine output and growth follow-up going?", "What food, fluids, supplements and practical help are available to the parent?"], "try": ["Build one manageable meal-support action rather than a long ideal menu.", "Keep adult and infant supplement records separate and check product concentration.", "Explain production versus transfer without promising a milk-boosting food."], "refer": ["Seek urgent medical assessment now for an infant with poor feeding, unusual sleepiness or reduced urine.", "Refer persistent feeding pain, transfer concerns, growth concerns or breast symptoms with fever for appropriate assessment."], "reflection": "What would you say to a parent whose preferred feeding plan differs from your expectations, while still checking safety?"}, "sources": [{"label": "PHAC: breastfeeding guidance", "url": "https://www.canada.ca/en/public-health/services/publications/healthy-living/maternity-newborn-care-guidelines-chapter-6.html"}, {"label": "WHO: physiological basis of breastfeeding", "url": "https://ncbi.nlm.nih.gov/books/NBK148970/"}, {"label": "NHS: milk supply", "url": "https://www.nhs.uk/best-start-in-life/baby/feeding-your-baby/breastfeeding/breastfeeding-challenges/milk-supply/"}, {"label": "PHAC: postpartum nutrition", "url": "https://www.canada.ca/en/public-health/services/child-infant-health/postpartum-health-guide.html"}, {"label": "Health Canada: vitamin values", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-vitamins.html"}, {"label": "mineral values", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-elements.html"}, {"label": "British Columbia: iron deficiency assessment and management", "url": "https://www2.gov.bc.ca/gov/content/health/practitioner-professional-resources/bc-guidelines/iron-deficiency"}, {"label": "NIH: iodine", "url": "https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/"}, {"label": "CDC: B12 and breastfeeding", "url": "https://www.cdc.gov/breastfeeding-special-circumstances/hcp/diet-micronutrients/vitamin-b12.html"}, {"label": "National Academies: choline reference intake", "url": "https://www.ncbi.nlm.nih.gov/books/NBK114308/"}, {"label": "Health Canada: pregnancy and breastfeeding eating advice", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/life-stages/pregnant-breastfeeding.html"}, {"label": "Health Canada: birth-to-six-month recommendations", "url": "https://www.canada.ca/en/health-canada/services/canada-food-guide/resources/nutrition-healthy-term-infants/nutrition-healthy-term-infants-recommendations-birth-six-months.html"}, {"label": "Canadian Paediatric Society: allergy prevention", "url": "https://cps.ca/en/documents/position/dietary-exposures-and-allergy-prevention"}, {"label": "Health Canada: mercury advice", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/food-safety/chemical-contaminants/environmental-contaminants/mercury/mercury-fish.html"}, {"label": "Health Canada: caffeine", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/food-safety/food-additives/caffeine-foods.html"}, {"label": "American Academy of Pediatrics: dehydration signs", "url": "https://www.healthychildren.org/English/health-issues/injuries-emergencies/Pages/dehydration.aspx"}, {"label": "NHS: mastitis", "url": "https://www.nhs.uk/conditions/mastitis/"}]}, "lesson-5": {"title": "Infant Nutrition", "kicker": "Practise safe feeding decisions, not just a list of first foods", "steps": [{"id": "l5-interactive-1", "title": "Look at the feeding relationship first", "referenceSection": "l5-2", "teach": ["Infant feeding combines nourishment, development and a relationship. Ask about age, term or preterm history, current feeding method, growth follow-up and caregiver goals before suggesting changes. Breastmilk and commercial infant formula are appropriate feeding pathways; an adult plant beverage, cow’s milk or a homemade mixture is not an equivalent early-infant replacement.", "Responsive feeding attends to hunger and fullness cues rather than forcing every feed to match a predetermined volume. Caregivers may notice turning toward food and opening the mouth, then turning away or closing the mouth. Growth assessment uses patterns and clinical context, not a judgement from one bottle volume or an infant’s appearance."], "type": "choice", "prompt": "A caregiver worries that their infant does not finish every bottle. What is the most useful first response?", "options": [{"label": "Insist the infant finish a fixed volume every time.", "feedback": "This ignores fullness cues and does not assess whether the overall pattern is appropriate.", "correct": false}, {"label": "Diagnose underfeeding because unfinished bottles prove inadequate intake.", "feedback": "A single volume does not establish adequacy or a diagnosis; review the wider feeding and health picture.", "correct": false}, {"label": "Ask about hunger and fullness cues, usual feeds, urine and growth follow-up before interpreting the unfinished bottle.", "feedback": "Correct. The single observation needs context; this approach also leaves room to identify safety concerns.", "correct": true}]}, {"id": "l5-interactive-2", "title": "Vitamin D: calculate the unit, not the drop", "referenceSection": "l5-4", "teach": ["Canadian guidance recommends 400 IU vitamin D daily for breastfed and partially breastfed infants. Infants receiving only commercial formula do not routinely need an additional vitamin D supplement under that guidance, although clinicians may individualize advice. The parent’s routine supplement does not replace the infant’s recommendation.", "For vitamin D, one microgram equals 40 IU, so a unit conversion is possible. A volume or drop count cannot be inferred without the product’s concentration. Check the exact bottle, measuring device and caregiver’s method. If the label is unclear, involve a pharmacist before dosing; do not assume all infant products work the same way."], "type": "number", "prompt": "Using 1 mcg vitamin D = 40 IU, how many micrograms equal 400 IU?", "answer": 10, "tolerance": 0, "unit": "mcg", "explanation": "400 ÷ 40 = 10 mcg. This does not tell you a drop count or volume; those depend on the specific product."}, {"id": "l5-interactive-3", "title": "Formula safety starts before the feed", "referenceSection": "l5-5", "teach": ["Powdered formula is not sterile. Ready-to-feed liquid, concentrate and powder are different products, and preparation instructions depend on product, infant risk and whether a feed is used immediately or prepared ahead. Higher-risk infants may need a different approach. Use complete current instructions with the care team, not a remembered fragment as a recipe.", "Never dilute formula to stretch supply or improvise a homemade substitute. Check the exact scoop and powder-to-water ratio when products change. Safe water, clean equipment, cooling, refrigeration and discard instructions all matter. If cost or availability is the barrier, address it without blame and connect the family with appropriate support rather than endorse an unsafe workaround."], "type": "sort", "prompt": "Distinguish a useful safety check from a dangerous shortcut.", "categories": ["Useful safety check", "Dangerous shortcut"], "items": [{"label": "Re-read the preparation directions when the product changes.", "category": 0, "feedback": "Products and scoops can differ; previous instructions may not transfer."}, {"label": "Add extra water when the tin is running low.", "category": 1, "feedback": "Dilution changes nutrient and fluid balance. Address the supply problem with appropriate support."}, {"label": "Ask about cleaning, water and storage arrangements.", "category": 0, "feedback": "The process matters as well as the formula itself."}, {"label": "Use a homemade mixture because the ingredients are natural.", "category": 1, "feedback": "Natural ingredients do not establish infant nutritional adequacy or microbial safety."}, {"label": "Assume powdered formula is sterile once the tin is opened.", "category": 1, "feedback": "Powdered formula is not sterile; safe handling remains essential."}]}, {"id": "l5-interactive-4", "title": "Complementary means in addition", "referenceSection": "l5-6", "teach": ["Around six months, developmental readiness and nutrition needs support complementary feeding. Look for good head control, appropriate supported sitting for feeding, interest in food and the ability to accept it rather than immediately push it out. Readiness is more than a calendar date, and breastmilk or formula continues as foods gradually expand.", "Iron-rich foods deserve early attention and should be offered a few times daily. Progress toward varied, developmentally appropriate textures; Canadian guidance advises introducing lumpy textures no later than nine months. Suitable family foods can be adapted rather than replaced with a rigid branded-food schedule. Persistent swallowing or feeding difficulty calls for assessment, not simply more texture practice."], "type": "explore", "prompt": "Predict what each first-food pattern contributes and what still needs attention.", "panels": [{"label": "Fruit purées at every meal", "text": "Fruit can contribute to variety, but a fruit-only pattern misses deliberate iron-rich choices and broader food progression. Review the whole day, including continued milk feeding."}, {"label": "Soft lentils with soft vegetables", "text": "This can be an adaptable iron-containing family-food option with an appropriate texture. Check readiness and safe preparation; it is not a complete daily prescription."}, {"label": "Smooth foods indefinitely because lumps feel worrying", "text": "Explore the concern and appropriate texture progression. Swallowing difficulty needs qualified assessment rather than forcing textures or keeping every food smooth without review."}]}, {"id": "l5-interactive-5", "title": "Iron reference does not mean iron drops", "referenceSection": "l5-7", "teach": ["Iron supports oxygen transport and development. As infants grow, birth stores do not remove the need for iron-rich complementary foods. Meat, fish, tofu, cooked legumes, eggs and iron-fortified infant cereal provide options; vitamin-C-containing foods can support absorption of plant iron. Ask which choices fit the family’s eating pattern and preparation skills.", "The iron RDA for ages 7–12 months is 11 mg daily total intake. This is not a direction to give every infant 11 mg of iron drops. Supplement decisions require clinical assessment, particularly for premature or low-birth-weight infants or suspected deficiency. A trainee can review the pattern without diagnosing deficiency or selecting a treatment dose."], "type": "choice", "prompt": "A caregiver sees the 11 mg iron reference and asks which drops to buy. What is the best explanation?", "options": [{"label": "No infant ever needs an iron supplement if they eat some cereal.", "feedback": "Some infants need individualized supplementation; one food does not settle clinical needs.", "correct": false}, {"label": "It is a total-intake reference, not an automatic supplement dose; review iron-rich foods and ask the infant’s clinician about individual supplementation.", "feedback": "Correct. You preserve the role of food and the distinction between population reference and clinical dosing.", "correct": true}, {"label": "Buy drops supplying exactly 11 mg for every infant.", "feedback": "That turns a total-intake reference into a universal supplement prescription.", "correct": false}]}, {"id": "l5-interactive-6", "title": "Choking prevention and allergy are different", "referenceSection": "l5-8", "teach": ["A food can be nutritionally suitable but unsafe in its current shape. Whole nuts, whole grapes, hard raw vegetables and sticky spoonfuls of nut butter are choking concerns. Seat the infant upright, supervise closely and modify texture and shape appropriately. Caregivers should learn infant choking first aid from an accredited provider.", "Allergen introduction answers a different question. For most infants, common allergens can be introduced around six months in safe forms; higher-risk history needs care-team discussion. Once tolerated, regular ongoing ingestion matters. An existing allergy or previous reaction needs an individualized plan, not a home re-challenge. Early introduction never means offering whole peanuts."], "type": "sort", "prompt": "Identify the primary issue each statement is addressing.", "categories": ["Shape and choking safety", "Allergy assessment or introduction"], "items": [{"label": "Whole nuts are not a safe infant serving form.", "category": 0, "feedback": "The immediate problem is a choking-hazard form, regardless of allergy history."}, {"label": "A previous reaction should be reviewed before the food is offered again.", "category": 1, "feedback": "A possible allergy needs professional guidance; do not conduct a home re-challenge."}, {"label": "Smooth peanut butter can be thinned into an already-tolerated food.", "category": 0, "feedback": "This illustrates changing a hazardous thick spoonful into an appropriate form; individual allergy advice still matters."}, {"label": "Once an allergen is tolerated, ongoing ingestion supports tolerance.", "category": 1, "feedback": "This concerns allergen exposure, not a guarantee that every shape is safe."}]}, {"id": "l5-interactive-7", "title": "Milk transitions are not simple swaps", "referenceSection": "l5-10", "teach": ["Under Canadian guidance, homogenized cow’s milk may become a main milk drink between nine and twelve months once the infant regularly eats a variety of iron-rich foods. It does not require stopping breastfeeding. Cow’s milk should be limited to no more than 750 mL daily because large volumes can displace other foods.", "Plant beverages are not interchangeable with infant formula. Foodborne precautions also remain important during food introduction: no honey before twelve months, including pasteurized honey or honey added to foods. Ordinary cooking is not a reliable safety fix for infant honey exposure. Avoid raw or undercooked animal foods and unpasteurized products, and use safe storage and preparation."], "type": "explore", "prompt": "Predict why each proposed swap needs more thought.", "panels": [{"label": "Plant beverage instead of commercial formula", "text": "These are not equivalent infant feeds. Clarify age, feeding pattern and clinical needs instead of choosing by the word milk on the carton."}, {"label": "Large amounts of cow’s milk once solids begin", "text": "Timing and iron-rich food variety matter; high volumes can displace foods. Apply the age-specific guidance rather than treating solids as permission for unlimited milk."}, {"label": "Honey baked into a snack for a ten-month-old", "text": "The no-honey advice still applies. Pasteurization or ordinary cooking is not a dependable way to make it safe for an infant."}]}, {"id": "l5-interactive-8", "title": "Handle the risk and its practical cause", "referenceSection": "l5-13", "teach": ["Poor feeding with reduced urine, unusual sleepiness or other dehydration signs needs prompt care. Repeated vomiting, blood in stool, suspected reactions, swallowing difficulty and growth concerns also require clinical assessment rather than repeated food experiments. Severe breathing difficulty, collapse or a suspected severe allergic reaction requires emergency care immediately.", "Safety and compassion belong together. A caregiver stretching formula may face an urgent financial problem, not a knowledge deficit alone. Respond without blame, address the infant’s immediate symptoms and connect the family with feeding support. Document observations and actions, not an unconfirmed diagnosis. Emergency care takes priority over collecting a detailed food diary."], "type": "choice", "prompt": "A caregiver has diluted formula to save money. The infant is sleepier and has fewer wet diapers. Which response is strongest?", "options": [{"label": "Arrange urgent medical assessment, explain the dilution concern without blame and help connect the family to immediate feeding support.", "feedback": "Correct. This addresses both current risk and the practical cause without substituting education for care.", "correct": true}, {"label": "Give the correct ratio and wait until the next routine appointment.", "feedback": "Correct preparation advice matters, but the infant’s symptoms require urgent assessment now.", "correct": false}, {"label": "Suggest a homemade formula until finances improve.", "feedback": "That introduces additional nutritional and contamination risks rather than solving the safety problem.", "correct": false}]}], "practice": {"takeaway": "What this means for my practice: connect nutrition, readiness and safe preparation—and act promptly when an infant is unwell.", "ask": ["What is the infant’s age, feeding history and current growth follow-up?", "Can the caregiver show the actual formula or vitamin D label and preparation method?", "What hunger, fullness, readiness or swallowing cues are being noticed?"], "try": ["Practise a label teach-back without asking anyone to share personal patient data.", "Adapt one familiar iron-rich family food to a developmentally appropriate safe form.", "Separate allergen timing from choking-safe preparation in your explanation."], "refer": ["Escalate poor feeding with reduced urine, unusual sleepiness or other dehydration concerns promptly.", "Refer reactions, persistent swallowing problems, growth concerns or individualized supplement questions; use emergency services for severe acute reactions."], "reflection": "How would you explain a formula-preparation safety concern in a way that also makes it safe for a caregiver to tell you they cannot afford enough formula?"}, "sources": [{"label": "Health Canada: infant nutrition", "url": "https://www.canada.ca/en/health-canada/services/infant-care/infant-nutrition.html"}, {"label": "Health Canada: homemade formula safety", "url": "https://www.canada.ca/en/health-canada/services/canada-food-guide/resources/nutrition-healthy-term-infants/safety-homemade-infant-formulas-canada.html"}, {"label": "Canadian Paediatric Society: feeding in the first year", "url": "https://caringforkids.cps.ca/handouts/healthy-living/feeding_your_baby_in_the_first_year"}, {"label": "HealthLink BC: infant vitamin D and dose measurement", "url": "https://www.healthlinkbc.ca/sites/default/files/documents/hfile-69m.pdf"}, {"label": "Health Canada: preparing powdered formula", "url": "https://www.canada.ca/en/health-canada/services/milk-infant-formula/preparing-handling-powdered-infant-formula.html"}, {"label": "Health Canada: six-to-24-month recommendations", "url": "https://www.canada.ca/en/health-canada/services/canada-food-guide/resources/nutrition-healthy-term-infants/nutrition-healthy-term-infants-recommendations-birth-six-months/6-24-months.html"}, {"label": "INSPQ: first foods", "url": "https://www.inspq.qc.ca/en/tiny-tot/child/feeding/foods/first-foods"}, {"label": "NIH: iron reference intakes", "url": "https://ods.od.nih.gov/factsheets/Iron-Consumer/"}, {"label": "INSPQ: choking prevention", "url": "https://www.inspq.qc.ca/en/tiny-tot/child/feeding/foods/choking-risks"}, {"label": "INSPQ: introducing foods", "url": "https://www.inspq.qc.ca/en/tiny-tot/child/feeding/foods/how-to-introduce-foods"}, {"label": "Canadian Paediatric Society: dietary exposure guidance", "url": "https://cps.ca/en/documents/position/dietary-exposures-and-allergy-prevention"}, {"label": "Alberta Health Services: allergic-reaction care", "url": "https://myhealth.alberta.ca/health/AfterCareInformation/pages/conditions.aspx?hwid=ug5356"}, {"label": "Health Canada: infant botulism", "url": "https://www.canada.ca/en/health-canada/services/food-safety-vulnerable-populations/infant-botulism.html?wbdisable=true"}, {"label": "Newfoundland and Labrador: foods to avoid", "url": "https://www.gov.nl.ca/healthyeating/baby/offering-healthy-foods/foods-to-avoid-for-baby/"}, {"label": "Canadian Paediatric Society: dehydration guidance", "url": "https://caringforkids.cps.ca/handouts/health-conditions-and-treatments/dehydration_and_diarrhea"}]}, "lesson-6": {"title": "Toddler and Preschooler Nutrition", "kicker": "Build calm structure, check developmental fit, support the whole day", "steps": [{"id": "l6-interactive-1", "title": "One unfinished meal has several possible stories", "referenceSection": "l6-2", "teach": ["Toddlers are learning to move, communicate, choose and feed themselves; preschoolers increasingly participate in group meals. Feeding is therefore a developmental task as well as nutrient provision. Slower growth after infancy can accompany a smaller appetite, and acceptance varies across days. One unfinished meal does not establish deficiency or inadequate parenting.", "Ask what changed around the time eating changed. Childcare, illness, uncomfortable stools, sleep, stress and meal timing are possibilities to explore, not diagnoses. Growth history and the whole pattern matter more than comparing siblings’ plates. Match expectations to chewing, swallowing, sensory and self-feeding skills as well as age."], "type": "explore", "prompt": "Predict which question could change your interpretation of dinner refusal.", "panels": [{"label": "A large snack just before dinner", "text": "Ask about timing and the whole day. Dinner appetite may reflect earlier nourishment rather than a problem with the dinner food."}, {"label": "No accessible food since lunch", "text": "Ask about transport, childcare and food access. The response should address the long gap, not merely teach the family a stricter schedule."}, {"label": "New discomfort during meals", "text": "Clarify the symptoms and consider appropriate assessment. Pain or swallowing difficulty should not be treated as ordinary defiance."}]}, {"id": "l6-interactive-2", "title": "Structure is not control of intake", "referenceSection": "l6-3", "teach": ["Adults provide suitable foods and predictable eating opportunities; children are supported in responding to hunger and fullness. Offer a familiar component, start with manageable amounts and allow more. Pressure, bargaining and rewards can intensify conflict. A flexible routine is not permission to withhold needed food when hunger, illness or individual care needs require adjustment.", "Distinguish setting up a meal from controlling every bite. Seated snacks, manageable utensils and accessible foods provide structure; demanding five bites before play controls intake. Looking, touching or smelling can be food exploration without compulsory tasting. A calmer meal or greater participation can be a useful outcome even before the quantity eaten changes."], "type": "sort", "prompt": "Place each action under supportive structure or pressure.", "categories": ["Supportive structure", "Pressure or intake control"], "items": [{"label": "Offer a familiar food alongside other meal components.", "category": 0, "feedback": "This makes participation possible without requiring a specific amount to be eaten."}, {"label": "Require five bites before outdoor play.", "category": 1, "feedback": "This turns play into leverage and disregards hunger and fullness."}, {"label": "Provide a seated snack after childcare.", "category": 0, "feedback": "A predictable opportunity can address a real gap while remaining responsive."}, {"label": "Praise a child only when the plate is empty.", "category": 1, "feedback": "This rewards intake rather than helping the child respond to their own cues."}, {"label": "Allow smelling a new food without requiring a taste.", "category": 0, "feedback": "Exploration can build familiarity without coercion."}]}, {"id": "l6-interactive-3", "title": "Count a beverage pattern without diagnosing", "referenceSection": "l6-5", "teach": ["The 12–24-month transition is not simply preschool advice with smaller portions. Breastfeeding may continue. For non-breastfed children in this age range, Canadian guidance recommends offering 500 mL homogenized 3.25% milk daily and limiting it to 750 mL so that it does not displace other foods. Breastfed children continue the infant vitamin D recommendation.", "Ask about total volume, timing and drinking method before concluding that a child will not eat. A beverage can contribute nutrients while replacing opportunities for food. Arithmetic can identify a pattern worth discussing; it cannot diagnose iron deficiency. Plant beverages are not equivalent main milk replacements before age two, and medical or vegan feeding needs warrant qualified planning."], "type": "number", "prompt": "In an illustrative record for a non-breastfed 20-month-old, milk servings are 250 mL, 200 mL and 300 mL. What is the daily total?", "answer": 750, "tolerance": 0, "unit": "mL", "explanation": "250 + 200 + 300 = 750 mL, the stated maximum rather than a target to aim for. Review the whole pattern and age-specific guidance; this does not diagnose a deficiency."}, {"id": "l6-interactive-4", "title": "Choose nutrient roles, not “perfect” foods", "referenceSection": "l6-4", "teach": ["Small appetites make nutrient-containing foods useful across meals and snacks. Iron, calcium, vitamin D and suitable fats deserve attention; fat is not an ingredient to eliminate from a young child’s diet. Familiar starches, iron-containing protein foods, produce and a source of fat can form a flexible meal-planning starting point.", "Reference values concern total intake, not automatic supplement doses. Canadian calcium and iron RDAs are 700 mg and 7 mg at ages 1–3, and 1,000 mg and 10 mg at ages 4–8. From age one, vitamin D’s RDA is 600 IU total intake. Review supplements and food sources together instead of stacking products to chase each number."], "type": "explore", "prompt": "Predict how each meal adjustment might help without pretending it creates a complete daily diet.", "panels": [{"label": "Soft rice, mashed lentils, cooked tomato and vegetable oil", "text": "This combines a familiar starch, an iron-containing protein food, produce and suitable fat. Check what the child actually accepts and can safely manage."}, {"label": "A beverage labelled “milk” at age three", "text": "Look beyond the name to protein, fortification and the whole pattern. Beverage labels do not guarantee nutritional equivalence."}, {"label": "A parent wants a separate pill for every reference value", "text": "Clarify total intake versus supplementation. Review actual foods and existing products with a qualified professional rather than automatically adding doses."}]}, {"id": "l6-interactive-5", "title": "Safety has more than one route", "referenceSection": "l6-6", "teach": ["Developmentally appropriate food shape and texture, upright seating and supervision help prevent choking. Whole grapes, whole nuts, popcorn, hard raw vegetables and thick spoonfuls of nut butter are examples of concerns. Ask how a snack is served: a food name alone does not describe whether its form is suitable for the child.", "Foodborne prevention is a separate task: pasteurized products, safe cooking, clean handling and appropriate refrigeration matter. Allergy management also needs an explicit plan shared with responsible adults. Do not conduct challenges or remove multiple foods without assessment. A severe immediate reaction or breathing problem requires emergency care rather than a diary or routine appointment."], "type": "sort", "prompt": "Match each action to the main safety problem it addresses.", "categories": ["Choking prevention", "Foodborne-illness prevention", "Allergy coordination"], "items": [{"label": "Seat and supervise a child while eating.", "category": 0, "feedback": "Position and supervision support safer eating; running with food in the mouth is unsafe."}, {"label": "Refrigerate perishable foods promptly.", "category": 1, "feedback": "Storage reduces foodborne risk; it does not change a food’s choking shape."}, {"label": "Share the existing allergy plan with childcare staff.", "category": 2, "feedback": "Responsible adults need a clear, verified plan; do not improvise a food challenge."}, {"label": "Modify a hard food’s shape and texture.", "category": 0, "feedback": "Safe presentation depends on the child’s developmental skills."}, {"label": "Keep raw meat and its juices separate from ready-to-eat foods during preparation.", "category": 1, "feedback": "Preparation hygiene addresses microbial risk independently of responsive feeding."}]}, {"id": "l6-interactive-6", "title": "Map home, childcare and the journey between", "referenceSection": "l6-7", "teach": ["The whole day may cross home, childcare and transport. Ask who provides breakfast, when lunch and snacks happen, whether containers are manageable and whether something familiar is available. Descriptive information is more useful than calling a child a good or bad eater. Shared routines work best when adults avoid shame and comparison.", "Food access changes which suggestions are realistic. Ask privately whether food runs out and whether there is equipment, refrigeration, storage and time. Budget education cannot create income. Respectful support may mean connecting the family with resources or using familiar affordable foods rather than requiring speciality purchases. Keep movement and play separate from earning or compensating for food."], "type": "choice", "prompt": "A family reports that the preschool lunchbox comes home full. Which first step gives you the most useful information?", "options": [{"label": "Tell the family to buy expensive specialist snacks immediately.", "feedback": "This assumes the problem and may add cost without improving access or participation.", "correct": false}, {"label": "Ask staff to withhold play until the lunch is finished.", "feedback": "This uses pressure and treats play as a reward for intake rather than addressing the feeding environment.", "correct": false}, {"label": "Ask about the setting, timing, container access, familiar foods and the child’s experience before changing the menu.", "feedback": "Correct. These details may explain the barrier and guide a realistic plan.", "correct": true}]}, {"id": "l6-interactive-7", "title": "Run a small, respectful mealtime experiment", "referenceSection": "l6-9", "teach": ["A useful counselling goal names a feasible action and something to observe. If a child eats foods separately at home but rejects mixed dishes at childcare, investigate preferences and context before insisting on tasting. Serving the same components separately with one familiar item may make the meal more approachable without requiring special foods.", "The experiment is not a guarantee of acceptance. Remove the pressure to taste, then observe comfort, participation and access rather than measuring success only in bites. Agree how caregivers and staff will review the change. If distress is extensive or swallowing is difficult, referral takes priority over repeatedly adjusting presentation or increasing pressure."], "type": "choice", "prompt": "Which trial best fits a four-year-old who dislikes mixed dishes at childcare but eats the components at home?", "options": [{"label": "Remove all mixed dishes permanently and promise the problem is solved.", "feedback": "A limited experiment is more informative than an absolute rule or a guarantee; broader difficulty may need assessment.", "correct": false}, {"label": "Offer separated components with a familiar item, remove the taste requirement and review comfort and participation with caregivers and staff.", "feedback": "Correct. This tests a specific environmental adjustment without coercion or a guaranteed outcome.", "correct": true}, {"label": "Hide every disliked ingredient and require a clean plate.", "feedback": "This does not address the child’s experience and maintains pressure around intake.", "correct": false}]}, {"id": "l6-interactive-8", "title": "Know when routine support is not enough", "referenceSection": "l6-8", "teach": ["Ordinary selectivity is not interchangeable with a clinically significant feeding problem. Persistent pain, coughing or choking during meals, loss of accepted textures, dehydration, very limited intake or growth concerns warrants assessment. Apparent body size cannot rule out serious nutritional difficulty. Acute breathing difficulty, inability to swallow or marked lethargy needs urgent care.", "Document what is observed and arrange appropriate medical, dietetic or feeding-team review rather than diagnosing from the number of accepted foods. A follow-up plan should name an action, who will do it and what triggers earlier help. Practical support can proceed alongside referral, but it must not delay the response to concerning symptoms."], "type": "sort", "prompt": "Choose the level of response that each situation calls for.", "categories": ["Routine supportive exploration", "Qualified assessment needed", "Urgent care"], "items": [{"label": "One unfinished dinner, with no other concerns reported.", "category": 0, "feedback": "Explore the whole-day pattern and context; one meal does not establish deficiency."}, {"label": "Repeated coughing and distress during meals.", "category": 1, "feedback": "Persistent swallowing or feeding concerns require qualified assessment rather than increased pressure."}, {"label": "Loss of previously managed textures.", "category": 1, "feedback": "A change in feeding ability warrants review; do not assume ordinary preference alone."}, {"label": "Acute inability to swallow or severe breathing difficulty.", "category": 2, "feedback": "Urgent care takes priority over routine nutrition counselling."}]}], "practice": {"takeaway": "What this means for my practice: provide calm structure, understand the whole day and recognise feeding concerns without diagnosing from a plate.", "ask": ["What changed when eating became difficult?", "What happens across home, childcare and the journey between?", "Are there pain, swallowing, growth, food-access or developmental concerns?"], "try": ["Replace one pressure-based phrase with neutral food language.", "Design one specific mealtime experiment and observe comfort as well as intake.", "Review beverage amounts and timing using the child’s actual age group."], "refer": ["Refer persistent pain, coughing or choking, loss of textures, very restricted intake or growth concerns.", "Use urgent care for acute breathing or swallowing difficulty, marked lethargy or other severe concerns."], "reflection": "What would you count as progress if the child does not eat more immediately but meals become calmer and participation improves?"}, "sources": [{"label": "Canadian Paediatric Society: picky eating", "url": "https://caringforkids.cps.ca/handouts/healthy-living/when_your_child_is_a_picky_eater"}, {"label": "Health Canada: children and adolescents", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/applying/advice-nutrition-different-life-stages/considerations-children-adolescents.html"}, {"label": "Health Canada mineral reference table", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-elements.html"}, {"label": "Health Canada vitamin reference table", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-vitamins.html"}, {"label": "Health Canada vitamin D", "url": "https://www.canada.ca/en/health-canada/services/nutrients/vitamin-d.html"}, {"label": "Health Canada infant nutrition", "url": "https://www.canada.ca/en/health-canada/services/infant-care/infant-nutrition.html"}, {"label": "Health Canada 6–24-month recommendations", "url": "https://www.canada.ca/en/health-canada/services/canada-food-guide/resources/nutrition-healthy-term-infants/nutrition-healthy-term-infants-recommendations-birth-six-months/6-24-months.html"}, {"label": "CDC choking prevention", "url": "https://www.cdc.gov/infant-toddler-nutrition/foods-and-drinks/choking-hazards.html"}, {"label": "Health Canada food safety for ages five and under", "url": "https://www.canada.ca/en/health-canada/services/publications/food-nutrition/safe-food-handling-children-ages-5-under.html"}, {"label": "CPS paediatric eating-disorder guidance", "url": "https://cps.ca/en/documents/position/eating-disorders"}]}, "lesson-7": {"title": "Child and Preadolescent Nutrition", "kicker": "See the school day through the child’s eyes.", "steps": [{"id": "l7-interactive-2", "title": "The lunch that comes home", "teach": ["School-age children increasingly eat where caregivers cannot directly observe them. Lunch periods, clubs, transport, friends and advertising become part of the nutrition environment. Children also develop practical skills: opening packaging, choosing between foods, reading simple labels and helping prepare meals. The counsellor’s question expands from “What is served?” to “Can this child comfortably access and eat it?”", "Canadian guidance recognizes childhood and adolescence as periods of growth and learning about food. Energy and nutrient adequacy remain central as children approach puberty. The food guide is a pattern to adapt, not a test that each meal must pass."], "type": "choice", "prompt": "An eight-year-old brings lunch home and is very hungry after school. What should you explore first?", "referenceSection": "l7-2", "options": [{"label": "What happens during lunchtime, including time and containers?", "feedback": "Yes. A usable eating opportunity depends on access, not just what was packed. Invite the child’s account before changing food.", "correct": true}, {"label": "Whether removing the afternoon snack will increase motivation", "feedback": "Withholding food does not solve an inaccessible lunch and ignores hunger. Investigate the school-day barrier first.", "correct": false}, {"label": "Whether lunch looks balanced in a photograph", "feedback": "A photograph cannot reveal a stuck lid, a short break or anxiety about asking for help.", "correct": false}]}, {"id": "l7-interactive-3", "title": "Read the age band", "teach": ["Children reach puberty at different times, so peers of the same age can vary in size and physical maturity. Do not use classmates or siblings as a growth standard. Activity should emphasize participation, skills and enjoyment rather than changing appearance.", "Selected Canadian RDAs: ages 4–8: calcium 1,000 mg/day and iron 10 mg/day; ages 9–13: calcium 1,300 mg/day and iron 8 mg/day , for both male and female table categories. These describe total intake, not tablets. Vitamin D’s RDA is 600 IU, or 15 micrograms, daily across these ages."], "type": "number", "prompt": "For a reference-table exercise, what is the calcium RDA for ages 9–13?", "referenceSection": "l7-3", "answer": 1300, "tolerance": 0, "unit": "mg/day", "explanation": "1,300 mg/day describes total usual intake, not a calcium-tablet dose. The ages 4–8 value is 1,000 mg/day; birthdays do not create abrupt biological changes."}, {"id": "l7-interactive-5", "title": "Time, tools, temperature and trust", "teach": ["Involving children in planning and packing lunches can improve practical food skills and help identify foods they will use. School meals can reflect taste, culture and budget.", "A useful original checklist is time, tools, temperature and trust . Time: how long is available after lining up? Tools: can the child manage the lid and utensils? Temperature: can perishables stay cold or hot food stay hot? Trust: can the child report an unpleasant experience without being punished for waste?"], "type": "sort", "prompt": "Match the observation to the most directly relevant next conversation.", "referenceSection": "l7-5", "categories": ["Usable lunch access", "Food safety", "Dignity and trust"], "items": [{"label": "A jar lid is too tight.", "category": 0, "feedback": "Try a container the child can open; more food knowledge will not loosen a lid."}, {"label": "A perishable lunch has no cooling arrangement.", "category": 1, "feedback": "Discuss an insulated bag and ice pack, alongside school requirements."}, {"label": "Classmates mock a cultural food.", "category": 2, "feedback": "Ask what the child wants; involve appropriate school support with permission rather than automatically removing the food."}, {"label": "Most of the break is spent queuing.", "category": 0, "feedback": "Explore usable eating time rather than blaming appetite."}]}, {"id": "l7-interactive-6", "title": "Spot the persuasive message", "teach": ["Children encounter marketing through characters, games, prizes and digital media. Their developmental stage can make persuasive intent difficult to recognize. Supporting media literacy and reducing exposure are complementary approaches.", "Original activity: compare two fictional cereal packages. One has a superhero and “power breakfast” slogan; the other is plain. Ask which information is an advertisement and which is a nutrition fact. Then ask whether either package reveals cost, taste, cultural fit or whether the child can actually access it. The exercise should build curiosity, not teach shame about enjoying a branded product."], "type": "explore", "prompt": "Predict which feature tells you about nutrition, which is advertising, and what is missing. Then open the panels.", "referenceSection": "l7-6", "panels": [{"label": "Superhero and “power breakfast”", "text": "These are persuasive features. Enjoying a branded cereal is not a moral failure, but its character does not establish nutrient content."}, {"label": "Nutrition information", "text": "Actual nutrition information answers specific composition questions. It does not establish whether a child’s whole pattern is adequate."}, {"label": "The unseen school day", "text": "Neither package reveals affordability, whether the child likes the food or whether there is time to eat. Ask about these conditions too."}]}, {"id": "l7-interactive-7", "title": "Respond without making thinness the goal", "teach": ["Preadolescents may start comparing bodies before adults expect it. Respond to comments with curiosity rather than a diet. “What happened that made you think you should eat less?” can uncover teasing, a video or a misunderstood classroom lesson. Do not reassure solely by saying a child is thin; that still makes thinness the condition for being acceptable.", "Canadian paediatric advice discourages dieting and appearance-focused commentary, emphasizing supportive conversations and a varied eating pattern. Weight-related bullying and preoccupation with food or body shape deserve attention."], "type": "choice", "prompt": "A preteen says, “My teammates skip bread to get faster.” Which reply protects nourishment and dignity?", "referenceSection": "l7-7", "options": [{"label": "You are already thin, so you do not need to diet.", "feedback": "This makes thinness the condition for reassurance and leaves the team message unexamined.", "correct": false}, {"label": "What have you heard, and how is it affecting eating? Growing bodies need reliable food.", "feedback": "Yes. Explore the message without endorsing restriction; arrange clinical assessment if restriction or symptoms persist.", "correct": true}, {"label": "Try avoiding bread only on rest days.", "feedback": "This endorses compensatory restriction. Food does not have to be earned through activity.", "correct": false}]}, {"id": "l7-interactive-8", "title": "Support activity without a product shortcut", "teach": ["For ordinary play and routine activity, water is generally appropriate. Sports drinks and caffeinated energy drinks are different products; energy drinks are not a hydration strategy for children. Longer, vigorous activity and extreme conditions may require an individualized plan.", "Original logistics exercise: for an after-school activity, identify where a snack can be stored, when it can be eaten and what meal follows. A sandwich portion and fruit may be more useful than buying a performance product. Ask whether transport costs or equipment fees are competing with the food budget. Do not suggest that food must be reduced on rest days to compensate for less movement."], "type": "explore", "prompt": "Predict the first useful question in each situation before opening its panel.", "referenceSection": "l7-8", "panels": [{"label": "After-school practice", "text": "Where can a snack be stored and when can it be eaten? Map the travel gap and meal afterward before recommending products."}, {"label": "An energy drink advertisement", "text": "Water generally suits ordinary activity. Caffeinated energy drinks are not child hydration strategies; demanding or prolonged conditions may need individualized planning."}, {"label": "A vegan family pattern", "text": "Clarify exclusions and reliable nutrient sources, especially B12. Respect the choice and seek dietetic planning when needed rather than assuming either deficiency or adequacy."}]}, {"id": "l7-interactive-9", "title": "Support, assessment or urgent help?", "teach": ["A counsellor can identify barriers, support food skills and facilitate referral. They should not diagnose nutritional deficiency, interpret growth in isolation or independently treat an eating disorder. Rapid or unexplained weight change, growth faltering, persistent food avoidance and delayed puberty warrant medical assessment regardless of apparent body size.", "Ask about pain, swallowing, fatigue, stool concerns, medication effects and distress without assuming one cause. Severe dehydration, fainting with illness or acute breathing problems require urgent clinical attention. A child repeatedly unable to eat should not be left with only a motivational worksheet."], "type": "sort", "prompt": "Sort by the response warranted—not by a diagnosis.", "referenceSection": "l7-9", "categories": ["Practical support within role", "Clinical assessment", "Urgent clinical attention"], "items": [{"label": "A child cannot open a container; no symptoms are reported.", "category": 0, "feedback": "Change the container and review whether access improves."}, {"label": "Persistent food avoidance and growth concerns are reported.", "category": 1, "feedback": "These require qualified assessment; do not interpret growth in isolation."}, {"label": "A child has acute breathing difficulty.", "category": 2, "feedback": "Seek emergency assistance rather than continuing food counselling."}, {"label": "The household sometimes runs out of food.", "category": 0, "feedback": "Ask which practical access supports are acceptable; do not require proof of healthy choices."}]}], "practice": {"takeaway": "What this means for my practice: make nourishment accessible before judging a child’s choices.", "ask": ["What happens at lunchtime from start to finish?", "Which foods, routines or school experiences feel difficult?", "Who can help with one practical barrier, with appropriate permission?"], "try": ["Map a school day with the child and caregiver.", "Choose one accessible food opportunity or container change without removing needed snacks.", "Review comfort and access, not an empty lunchbox or weight target."], "refer": ["Arrange clinical assessment for growth concerns, persistent avoidance, unexplained weight change or distress.", "Use urgent clinical help for acute breathing problems, severe dehydration or fainting with illness."], "reflection": "An untouched lunch returns home. What would you ask before giving advice, and what observation would make you refer?"}, "sources": [{"label": "Health Canada life-stage guidance", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/applying/advice-nutrition-different-life-stages/considerations-children-adolescents.html"}, {"label": "CPS physical activity guidance", "url": "https://caringforkids.cps.ca/handouts/healthy-living/physical_activity"}, {"label": "Health Canada mineral table", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-elements.html"}, {"label": "Health Canada vitamin table", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-vitamins.html"}, {"label": "Health Canada eating at school", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/healthy-eating-anywhere/school.html"}, {"label": "Health Canada safe school lunches", "url": "https://www.canada.ca/en/health-canada/services/seasonal-food-safety/safe-school-lunches.html"}, {"label": "Health Canada marketing and children", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/healthy-eating-recommendations/marketing-can-influence-your-choices/limiting-kids-exposure.html"}, {"label": "CPS dieting guidance", "url": "https://caringforkids.cps.ca/handouts/healthy-living/dieting_information_for_parents"}, {"label": "CPS energy and sports drinks", "url": "https://cps.ca/en/documents/position/energy-and-sports-drinks"}, {"label": "CPS vegetarian diets", "url": "https://caringforkids.cps.ca/handouts/healthy-living/vegetarian_diets_for_children_and_teens"}, {"label": "CPS eating-disorder assessment", "url": "https://cps.ca/en/documents/position/eating-disorders"}]}, "lesson-8": {"title": "Adolescent Nutrition", "kicker": "Build autonomy without leaving young people unsupported.", "steps": [{"id": "l8-interactive-2", "title": "Start with the teen’s agenda", "teach": ["Adolescence combines physical development with increasing independence. A young person may make more food decisions while still depending on adults for groceries, transport, money and permission to use a kitchen. School, employment, sports, relationships and online communities can all shape eating. Good counselling therefore asks what a teenager wants help with and what their day actually permits.", "Start with an open invitation: “What would make eating easier for you?” Possible goals include feeling less rushed, having food before practice, learning a low-cost meal or reducing conflict at home. Do not assume the desired goal is weight change. Explain the purpose of questions before asking about sensitive topics."], "type": "choice", "prompt": "A teenager attends because a caregiver booked the appointment. Which opening creates meaningful choice?", "referenceSection": "l8-2", "options": [{"label": "Which body changes would you like this plan to produce?", "feedback": "This assumes an appearance goal the teenager has not chosen.", "correct": false}, {"label": "What would make eating easier? We can discuss your day or one difficult situation.", "feedback": "Yes. Offer a real role in the conversation while leaving room for practical support.", "correct": true}, {"label": "Everything you say will remain secret in all circumstances.", "feedback": "Do not promise absolute secrecy. Explain privacy and its limits accurately within your service.", "correct": false}]}, {"id": "l8-interactive-3", "title": "Enough food before optimization", "teach": ["A varied eating pattern needs to provide enough food for development and ordinary living as well as activity. A visually impressive salad is not proof of sufficient energy. Nor does a large body exclude undernutrition. Before discussing supplements or detailed nutrient targets, identify missed meals, long gaps and unavailable food.", "Original assessment prompts: What happens between school and work? Is there food after evening practice? Are lunch breaks usable? Does nausea, pain, medication or anxiety interfere with eating? Are foods avoided for taste, culture, ethics, allergy, cost or fear? Distinguish a preference from an inability to access food and from distress that requires clinical review."], "type": "explore", "prompt": "Predict why the same “meal prep” advice might fail in these situations. Open the panels to compare.", "referenceSection": "l8-3", "panels": [{"label": "School to paid work", "text": "Prepared food may never be eaten without a usable break or storage. Map the actual gap and agree on a feasible opportunity."}, {"label": "An impressive salad", "text": "Appearance does not establish adequate overall food. Ask about the whole pattern and missed opportunities rather than praising a photograph."}, {"label": "Groceries run out", "text": "The missing ingredient may be access, not planning skill. Discuss acceptable support without making a teenager responsible for household finances."}]}, {"id": "l8-interactive-4", "title": "Reference value or pill dose?", "teach": ["For ages 14–18 , Canadian RDAs include calcium 1,300 mg/day , and iron 11 mg/day in the male table category and 15 mg/day in the female category . These are reference categories, not a complete individualized assessment. Vitamin D’s RDA is 15 micrograms (600 IU) daily .", "The reference values describe total usual intake, not doses to add automatically. Clinicians should consider menstrual losses, growth, medical conditions and individual physiology, including the needs of transgender and gender-diverse adolescents, without using table labels to invalidate identity."], "type": "number", "prompt": "In the supplied reference values for ages 14–18, what is the calcium RDA?", "referenceSection": "l8-4", "answer": 1300, "tolerance": 0, "unit": "mg/day", "explanation": "1,300 mg/day refers to total usual intake. It is not an instruction to add a 1,300 mg supplement. Individual assessment considers growth, health and relevant context."}, {"id": "l8-interactive-5", "title": "Understand the choice before advising", "teach": ["A well-planned vegetarian pattern can meet young people’s needs. A vegan pattern requires reliable vitamin B12 sources and attention to energy, protein, iron, calcium and other nutrients. A registered dietitian can help translate the pattern into affordable, usable meals.", "Ask what a label means in practice: does “plant-based” describe adding beans, excluding animal foods or eating only a few products? Respect ethical motivations. At the same time, ask neutrally whether foods are increasingly feared or rules are multiplying. Neither dismissing a vegetarian choice nor automatically declaring it nutritionally complete is good assessment."], "type": "sort", "prompt": "Route each statement toward the most useful next step.", "referenceSection": "l8-5", "categories": ["Clarify foods and adequacy", "Review product safety", "Arrange clinical assessment"], "items": [{"label": "“I am vegan for ethical reasons and need affordable meals.”", "category": 0, "feedback": "Respect the motivation; clarify available foods and arrange dietetic help for reliable B12 and overall adequacy."}, {"label": "“My pre-workout has ingredients I cannot identify.”", "category": 1, "feedback": "Record the product, amount, frequency and other supplements; refer uncertainty to a pharmacist or clinician."}, {"label": "“I keep adding forbidden foods because eating frightens me.”", "category": 2, "feedback": "Escalating fear and restriction warrant assessment, not merely a new menu."}, {"label": "“Plant-based means I sometimes add beans.”", "category": 0, "feedback": "Labels describe different patterns. Ask what is actually included and excluded."}]}, {"id": "l8-interactive-6", "title": "The athlete’s missing lunch", "teach": ["Distinguish ordinary activity from intensive training. Water generally suits routine activity; sports drinks may have a role in specific prolonged or demanding conditions, but caffeinated energy drinks are different and are not a substitute for hydration or food.", "Original planning exercise: place training on the weekly school timetable, then mark meals, snacks, travel and recovery time. Look for practical gaps rather than prescribing a universal athlete menu. A teenager travelling directly from school to practice might need food packed before leaving home and an accessible meal afterward. An athlete with repeated injuries, persistent fatigue or menstrual change needs assessment, not a stronger pre-workout product."], "type": "choice", "prompt": "A sixteen-year-old skips lunch before practice, uses energy drinks and reports dizziness. What is the safest first response?", "referenceSection": "l8-6", "options": [{"label": "Diagnose low iron and recommend iron tablets.", "feedback": "Dizziness does not establish iron deficiency. Do not diagnose or prescribe from this account.", "correct": false}, {"label": "Replace the energy drink with a stronger pre-workout.", "feedback": "A stimulant neither addresses missed food nor explains symptoms. Product escalation delays care.", "correct": false}, {"label": "Address symptoms and arrange timely medical assessment, urgently if severe or acute.", "feedback": "Yes. Once safety is addressed, collaboratively map lunch access, travel and food opportunities rather than weight loss.", "correct": true}]}, {"id": "l8-interactive-7", "title": "Separate the promise from the pressure", "teach": ["Dieting during adolescence can harm physical and psychological health. Weight bias and messages from family, peers, sport and media can shape food restriction. Canadian paediatric guidance supports moving away from weight-focused messaging toward sustainable health behaviours and supportive assessment.", "Original conversation practice: when a teen says, “I need to be smaller,” ask what they hope would change. The answer may involve bullying, selection for a team, clothing fit or feeling accepted. Acknowledge the experience without endorsing a restrictive plan. “You deserve to feel comfortable and supported; we can work on the eating difficulties and get help with the pressure” is more useful than debating whether they look thin enough."], "type": "explore", "prompt": "Predict what each message leaves out before revealing the response.", "referenceSection": "l8-7", "panels": [{"label": "“Look like this influencer”", "text": "An image is not evidence for a nutrition claim. Ask who benefits and whether the advice requires ignoring hunger or buying a product."}, {"label": "“You must be smaller to belong”", "text": "Explore teasing, team pressure or hoped-for acceptance without endorsing restriction. Support eating rather than debating whether the teen looks thin enough."}, {"label": "“Everyone on the team does it”", "text": "Popularity does not establish safety. Ask how the rule affects food, distress and symptoms; facilitate appropriate support."}]}, {"id": "l8-interactive-9", "title": "Do not wait for a visibly low weight", "teach": ["Eating disorders can occur at any body size. Persistent restriction, purging, rapid weight change, medical symptoms or major distress need timely clinical assessment. A generic meal plan is not eating-disorder treatment.", "Seek urgent medical help for acute concerns such as fainting, chest pain, confusion, severe dehydration or inability to maintain intake. Do not wait for a visibly low weight. Ask about safety within professional competence and follow local safeguarding procedures. Where serious restriction is suspected, do not prescribe an unsupervised refeeding regimen or interpret laboratory results without qualified care."], "type": "sort", "prompt": "Choose the appropriate response from the information provided.", "referenceSection": "l8-9", "categories": ["Practical planning", "Timely clinical assessment", "Urgent medical help"], "items": [{"label": "A teen needs lunch storage; no symptoms or restriction are reported.", "category": 0, "feedback": "Support a safe, usable eating opportunity and review it."}, {"label": "Persistent restriction and major distress are reported.", "category": 1, "feedback": "Eating disorders can occur at any size. A generic meal plan is not treatment."}, {"label": "A teen reports chest pain or confusion.", "category": 2, "feedback": "Seek urgent medical help rather than continuing routine nutrition education."}, {"label": "Ongoing menstrual changes or unexplained fatigue are reported.", "category": 1, "feedback": "These have multiple possible causes and warrant review, not a guessed deficiency."}]}], "practice": {"takeaway": "What this means for my practice: support agency, reliable nourishment and access to appropriate care.", "ask": ["What would you like help with, and how would you prefer to discuss it?", "Where do school, work, training or money interrupt eating?", "Are food rules, symptoms or pressure making eating harder?"], "try": ["Explain your role and privacy limits without promising absolute secrecy.", "Co-design one reliable eating opportunity and identify the support needed.", "Review whether the plan is usable and respectful, not whether appearance changed."], "refer": ["Persistent restriction, purging, menstrual changes, major distress or unexplained symptoms need clinical assessment.", "Chest pain, confusion, severe dehydration, fainting or inability to maintain intake require urgent medical help."], "reflection": "A teen describes skipping meals for team approval. How would you acknowledge their experience without endorsing restriction?"}, "sources": [{"label": "CPS adolescent confidentiality", "url": "https://cps.ca/en/documents/position/privacy-and-confidentiality-in-adolescent-health-care"}, {"label": "Health Canada mineral references", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-elements.html"}, {"label": "Health Canada vitamin references", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-vitamins.html"}, {"label": "NIH iron factsheet", "url": "https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/"}, {"label": "Health Canada vitamin D guidance", "url": "https://www.canada.ca/en/health-canada/services/nutrients/vitamin-d.html"}, {"label": "CPS vegetarian nutrition", "url": "https://caringforkids.cps.ca/handouts/healthy-living/vegetarian_diets_for_children_and_teens"}, {"label": "CPS sports and energy drinks", "url": "https://cps.ca/en/documents/position/energy-and-sports-drinks"}, {"label": "CPS energy-drink advice", "url": "https://caringforkids.cps.ca/handouts/preteens-and-teens/energy-drinks-and-sports-drinks"}, {"label": "CPS dangers of adolescent dieting", "url": "https://cps.ca/en/documents/position/dieting-in-adolescence"}, {"label": "Health Canada marketing literacy", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/healthy-eating-recommendations/marketing-can-influence-your-choices.html"}, {"label": "CPS community eating-disorder guidance", "url": "https://cps.ca/en/documents/position/eating-disorders"}]}, "lesson-9": {"title": "Adult Nutrition", "kicker": "Turn nutrition knowledge into a workable everyday plan.", "steps": [{"id": "l9-interactive-2", "title": "Two different adequacy questions", "teach": ["Energy adequacy and nutrient adequacy are different questions. Energy supplies fuel; nutrients support body functions. An eating pattern can provide enough energy while lacking certain nutrients, or contain nutritious foods while providing insufficient food overall. Canada's dietary guidance explicitly recognizes individual variation in energy needs and cautions that restrictive fad diets may pose nutritional risks.", "In a learning assessment, avoid jumping from a body-size description to a conclusion about intake. A person in any body size may skip meals or have a limited diet. Ask what happens on ordinary workdays and days off. The goal is to understand a pattern, not judge a single photograph or food choice."], "type": "explore", "prompt": "Predict why neither body size nor a meal photograph can settle adequacy. Then open each distinction.", "referenceSection": "l9-2", "panels": [{"label": "Enough energy?", "text": "Ask about overall amounts and usable eating opportunities. Food can look nutritious without supplying enough across the day."}, {"label": "Enough nutrients?", "text": "A pattern may supply sufficient energy while lacking particular nutrients. Variety, reliable sources and usual intake matter."}, {"label": "Enough context?", "text": "Work, access, health, reproductive life stage and personal priorities shape the assessment. Body size alone does not establish intake."}]}, {"id": "l9-interactive-3", "title": "Do not make every number a target", "teach": ["Dietary Reference Intakes describe requirements for healthy populations by life stage and reference categories. An RDA is intended to cover nearly all healthy people in its group. An AI is used when evidence cannot establish an RDA. The EAR estimates the requirement of half a healthy group; the UL is an upper boundary, not an optimal intake goal.", "None of these values diagnoses a person’s deficiency. A total-intake reference is not automatically a supplement dose, and one day below an RDA does not establish deficiency. Consider usual intake and clinical context; specialized needs require qualified assessment."], "type": "sort", "prompt": "Match the reference with its correct interpretation.", "referenceSection": "l9-3", "categories": ["Intake reference", "Group requirement estimate", "Upper boundary, not a goal"], "items": [{"label": "RDA: covers nearly all healthy people in a defined group.", "category": 0, "feedback": "It describes average daily intake, not automatically an extra supplement dose."}, {"label": "AI: used when evidence cannot establish an RDA.", "category": 0, "feedback": "It has a different evidentiary basis; it is not a diagnosis."}, {"label": "EAR: estimated requirement of half a healthy group.", "category": 1, "feedback": "Do not use it as a universal individual target."}, {"label": "UL: an upper intake boundary associated with low risk.", "category": 2, "feedback": "Higher is not automatically better; this is not an optimum to aim for."}]}, {"id": "l9-interactive-4", "title": "Keep the meal; adapt the pattern", "teach": ["Canada's Food Guide encourages vegetables and fruit, whole grains and protein foods, with plant proteins chosen more often; water is the preferred beverage. It also emphasizes cooking, enjoyment, awareness and eating with others. This is a pattern, not a moral ranking of people or a ban on celebration foods.", "The plate illustration uses approximately half vegetables and fruit, one-quarter whole grains and one-quarter protein foods. It depicts proportions, not an individualized portion prescription. A bowl, stew or shared platter can express the same principle. Frozen, canned and dried foods can fit."], "type": "choice", "prompt": "A person enjoys rice and chickpeas and wants an affordable addition. Which response best applies the food guide?", "referenceSection": "l9-4", "options": [{"label": "Replace the meal with an unfamiliar diet-branded product.", "feedback": "A product is not required. Start with food the person enjoys and can access.", "correct": false}, {"label": "Explore adding acceptable frozen spinach or tomatoes, considering cost and preference.", "feedback": "Yes. A familiar mixed dish can express a flexible pattern without becoming a rigid portion prescription.", "correct": true}, {"label": "Require every snack to match the plate illustration exactly.", "feedback": "The illustration represents a pattern, not a requirement that every snack be perfectly divided.", "correct": false}]}, {"id": "l9-interactive-5", "title": "Calculate, then state the limit", "teach": ["Carbohydrate, protein and fat are all relevant to a varied diet. Canada's reference tables list adult macronutrient distribution ranges rather than requiring a single universal ratio: carbohydrate 45–65%, fat 20–35% and protein 10–35% of energy. The adult protein RDA is 0.8 g/kg/day for healthy adults; it is not a treatment prescription or proof that every person benefits from the same intake.", "For study, connect foods to overlapping contributions rather than exclusive boxes. Beans offer protein and fibre; nuts provide fat and protein; yogurt can contribute protein and calcium. “Protein food” does not mean a food contains only protein. Likewise, evaluating fat involves food sources and the broader pattern, not simply avoiding every food with fat."], "type": "number", "prompt": "For a learning example, apply the healthy-adult protein RDA of 0.8 g/kg/day to a fictional 70 kg adult. What is the result?", "referenceSection": "l9-5", "answer": 56, "tolerance": 0, "unit": "g/day", "explanation": "70 × 0.8 = 56 g/day. This demonstrates a reference calculation, not an individualized prescription for someone with illness or specialized needs."}, {"id": "l9-interactive-6", "title": "Ask without diagnosing", "teach": ["Vitamin B12: animal-source and fortified foods provide dependable sources. A vegan pattern needs intentional reliable provision. Certain medicines or absorption conditions can complicate status; changing food alone may not address a clinical deficiency.", "Vitamin D: Health Canada advises people aged 2–50 to eat vitamin-D-containing foods daily or take 400 IU (10 micrograms) daily. For those 51 and older, it recommends a daily 400 IU supplement as well as vitamin-D-containing foods. This public-health supplement advice is distinct from a total-intake reference value or treatment dose."], "type": "explore", "prompt": "Predict the safe next question in each case, then open the panel.", "referenceSection": "l9-6", "panels": [{"label": "Fatigue and iron", "text": "Ask about reported symptoms and encourage appropriate assessment. Fatigue does not establish iron deficiency or justify treatment-dose iron."}, {"label": "A vegan pattern", "text": "Ask about dependable B12 sources and the whole pattern. Review actual fortified-food labels; not all plant beverages are equivalent."}, {"label": "Vitamin D already in use", "text": "Clarify existing products and clinical advice. Public-health supplement advice differs from total-intake references and deficiency treatment."}]}, {"id": "l9-interactive-8", "title": "Access is not motivation", "teach": ["Food insecurity refers to inadequate or uncertain food access because of financial constraints. It is not equivalent to poor cooking knowledge. Canadian research links it with household financial circumstances and adverse health outcomes.", "Ask permission before discussing money: “Would it help to consider food cost or access?” Also ask about transport, a refrigerator, a usable kitchen and time. Suggesting bulk purchases to someone without storage can increase waste. Suggesting daily fresh shopping to a shift worker can create another impossible job. With consent, help identify practical community or income-support pathways without promising eligibility or treating emergency food aid as a complete solution."], "type": "sort", "prompt": "Match the obstacle to a response that addresses it.", "referenceSection": "l9-8", "categories": ["Practical environment support", "Accessible food education", "Consent-based resource navigation"], "items": [{"label": "No refrigerator is available at work.", "category": 0, "feedback": "The plan must fit safe storage and the work environment."}, {"label": "Someone wants help reading a fortified beverage label.", "category": 1, "feedback": "Teach the relevant comparison using actual products and personal priorities."}, {"label": "There is not enough money for food.", "category": 2, "feedback": "Ask permission to explore acceptable community or income-support pathways; budgeting does not fix inadequate income."}, {"label": "Bulk buying is suggested without storage space.", "category": 0, "feedback": "Adapt to real storage and transport rather than interpreting difficulty as low motivation."}]}, {"id": "l9-interactive-10", "title": "Design the shift-work experiment", "teach": ["Mina, 34, reports missing lunch, then arriving home extremely hungry. She asks for a strict meal plan but has unpredictable breaks and no microwave. First clarify whether she wants more structure, fewer decisions or help with symptoms. Ask about refrigeration, food access and any medical issues; do not assume her difficulty is discipline.", "An original agreed experiment could be assembling a suitable cold meal on two shifts, using foods she already likes and can store safely. A second option is an accessible snack when a full meal break is delayed. Let Mina select the feasible option. Review practicality and satisfaction rather than grading perfection. Persistent dizziness, marked fatigue or unexplained weight changes warrant medical review; meal planning is not a diagnostic test."], "type": "choice", "prompt": "Mina has unpredictable breaks and no microwave. Which first experiment fits?", "referenceSection": "l9-10", "options": [{"label": "A strict hot-meal timetable regardless of breaks", "feedback": "This adds structure on paper while ignoring why eating is difficult.", "correct": false}, {"label": "A macronutrient spreadsheet before discussing access", "feedback": "Calculations do not create a break or a safe place to store food.", "correct": false}, {"label": "Let Mina choose a safely stored cold meal or accessible snack trial on two shifts.", "feedback": "Yes. Clarify her goal and storage first; review practicality and satisfaction, not perfection.", "correct": true}]}], "practice": {"takeaway": "What this means for my practice: combine nutritional understanding with one feasible experiment chosen by the person.", "ask": ["What would you like eating to make easier?", "What food, equipment, breaks and storage are available?", "What medical advice, symptoms or supplements should we account for?"], "try": ["Separate questions about energy, nutrients and practical access.", "Adapt a familiar meal or routine instead of imposing your own.", "Agree on a small experiment and review what helped or prevented it."], "refer": ["Persistent dizziness, marked fatigue, unexplained weight change or digestive symptoms warrant clinical assessment.", "Highly restricted patterns or conditions needing individualized targets warrant registered dietitian or clinician input."], "reflection": "A calculated plan is not used. What evidence would help distinguish an unsuitable plan from a need for more education?"}, "sources": [{"label": "Health Canada: foundations", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/section-1-foundation-healthy-eating.html"}, {"label": "Health Canada: DRI definitions", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/definitions-relationship-risk-inadequacy-risk-adverse-effects.html"}, {"label": "Healthy eating recommendations", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/healthy-eating-recommendations.html"}, {"label": "Food guide plate", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/cooking/make-healthy-meals-plate.html"}, {"label": "Health Canada: macronutrient reference values", "url": "https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-macronutrients.html"}, {"label": "NIH: iron", "url": "https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/"}, {"label": "NIH: vitamin B12", "url": "https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/"}, {"label": "Health Canada: vitamin D", "url": "https://www.canada.ca/en/health-canada/services/nutrients/vitamin-d.html"}, {"label": "Alberta: lifestyle changes", "url": "https://myhealth.alberta.ca/HealthTopics/perimenopause-menopause-pathway/Pages/lifestyle-changes.aspx"}, {"label": "NIDDK: constipation and nutrition", "url": "https://www.niddk.nih.gov/health-information/digestive-diseases/constipation/eating-diet-nutrition"}, {"label": "Statistics Canada: household vulnerability", "url": "https://www150.statcan.gc.ca/n1/pub/82-003-x/2025012/article/00001-eng.htm"}]}, "lesson-10": {"title": "Nutrition and Older Adults", "kicker": "Protect nourishment, function and choice in older adulthood.", "steps": [{"id": "l10-interactive-2", "title": "Find the difficult step", "teach": ["Older adulthood includes people with very different abilities, health conditions, living arrangements and goals. Someone may travel independently at 85 while another person needs substantial support at 65. Ask what matters: preparing breakfast, recovering after hospitalization, enjoying family meals or maintaining enough strength to shop. Nutrition is part of functioning and quality of life, not merely a list of nutrients.", "Age-related changes can affect appetite, taste, smell, thirst and the practical ability to buy or prepare food. Medicines, reduced income, living alone and changes in the home environment can also influence eating. These factors require individual questions, not assumptions that all older adults are frail or forgetful."], "type": "choice", "prompt": "An older adult says, “I do not eat much.” What is the most useful opening?", "referenceSection": "l10-2", "options": [{"label": "Everyone needs less food as they get older.", "feedback": "Age does not explain the difficulty. This risks normalizing inadequate intake.", "correct": false}, {"label": "Which part of eating is easiest, and which takes the most effort?", "feedback": "Yes. Separate shopping, opening, cooking, chewing, swallowing and enjoyment before selecting an intervention.", "correct": true}, {"label": "Ask the adult child to answer everything.", "feedback": "Address the older person directly and ask whom they want involved. Age does not remove autonomy.", "correct": false}]}, {"id": "l10-interactive-3", "title": "Nutritious is not the same as enough", "teach": ["Some older adults need less energy as activity and body composition change, while nutrient requirements remain important. Others need additional support because illness or recovery makes adequate eating difficult. Avoid the blanket instruction to eat less because of age. The practical question is whether the person can obtain enough food and nutrients for their situation.", "The National Institute on Aging encourages nutrient-dense variety and protein foods across the day, including options such as legumes, fish, dairy or fortified soy products."], "type": "explore", "prompt": "Predict why each apparently sensible plan might fail, then open its explanation.", "referenceSection": "l10-3", "panels": [{"label": "A large low-energy meal", "text": "Someone with a small appetite may not manage enough. Ask whether the food is nutritious and whether sufficient food is actually eaten."}, {"label": "An automatic “eat less” rule", "text": "Some people have lower energy needs; others struggle during illness or recovery. Age alone does not prescribe restriction."}, {"label": "An elaborate daily menu", "text": "A menu can demand more effort than someone can sustain. Practical effort and enjoyment belong in the plan."}]}, {"id": "l10-interactive-4", "title": "Observe function; do not assign a diagnosis", "teach": ["Sarcopenia is a muscle condition, not simply looking thin. The European consensus emphasizes low strength, confirms the condition with reduced muscle quantity or quality, and uses poor physical performance to indicate severity. It can occur before older adulthood. Screening and diagnosis require appropriate assessment; a counsellor should not label someone from age, body size or a single observation.", "A useful counselling distinction is body weight versus function . Stable weight does not prove stable muscle function. Ask about changes in carrying groceries or rising from a chair as conversation prompts, not as a substitute for standardized testing. New weakness or deteriorating function deserves clinical evaluation."], "type": "sort", "prompt": "Sort each action by its role.", "referenceSection": "l10-4", "categories": ["Appropriate observation or support", "Clinical assessment needed", "Unsupported conclusion"], "items": [{"label": "Ask about a change in carrying groceries.", "category": 0, "feedback": "This is a conversation prompt, not a substitute for standardized assessment."}, {"label": "Arrange evaluation for new weakness.", "category": 1, "feedback": "Functional decline needs assessment, not an automatic supplement."}, {"label": "Declare sarcopenia because someone looks thin.", "category": 2, "feedback": "Sarcopenia is not diagnosed from appearance or age."}, {"label": "Explore acceptable protein foods at different meals.", "category": 0, "feedback": "Support an achievable pattern while individualized clinical targets remain with qualified professionals."}]}, {"id": "l10-interactive-5", "title": "A supplement does not replace assessment", "teach": ["Health Canada's public advice for people aged 51 and older is a daily supplement providing 400 IU (10 micrograms) of vitamin D , alongside vitamin-D-containing foods. Do not confuse this supplement recommendation with the total-intake RDA or a clinical deficiency-treatment regimen. Provincial or condition-specific recommendations can differ; review individual advice with the person's clinician or pharmacist.", "Calcium-containing foods and adequate overall eating remain relevant; a vitamin-D pill does not replace meals. If someone avoids dairy, investigate suitable fortified alternatives rather than assuming every plant beverage contains equivalent nutrients. Read the label for the actual product."], "type": "explore", "prompt": "Predict what to clarify before recommending another product.", "referenceSection": "l10-5", "panels": [{"label": "Vitamin D in the cupboard", "text": "Ask what is taken and what advice is in place. Public-health supplement advice differs from a total-intake RDA or treatment regimen."}, {"label": "Avoiding dairy", "text": "Check actual calcium-containing or fortified alternatives rather than assuming all plant beverages contribute the same nutrients."}, {"label": "Memory changes and B12", "text": "Do not label memory changes as B12 deficiency or promise a cure. Suspected deficiency or neurological symptoms require clinical assessment."}]}, {"id": "l10-interactive-6", "title": "Hydration within the existing care plan", "teach": ["Thirst may become less reliable with age. Regular opportunities to drink can help, and fluids may come from beverages and foods. Québec guidance recommends gradual fibre increases and regular fluids rather than relying entirely on thirst.", "This does not justify a universal instruction to drink a fixed large volume. Kidney disease, heart conditions and prescribed fluid restrictions require clinical coordination. Ask what advice the person already follows. Practical barriers also matter: a heavy jug, fear of bathroom access or inability to open a bottle will not disappear after a lecture about hydration."], "type": "choice", "prompt": "A person finds their jug heavy and reports a prescribed fluid restriction. Which response fits your role?", "referenceSection": "l10-6", "options": [{"label": "Recommend a fixed large daily water volume.", "feedback": "A universal volume may conflict with existing care. Clarify restrictions with the treating team.", "correct": false}, {"label": "Stop the restriction because thirst becomes less reliable.", "feedback": "Do not override clinical instructions. General knowledge about thirst is not authority to alter treatment.", "correct": false}, {"label": "Clarify existing advice and explore a manageable cup within that plan.", "feedback": "Yes. Address the physical barrier without changing prescribed limits; review whether the arrangement helps.", "correct": true}]}, {"id": "l10-interactive-7", "title": "Chewing is not swallowing safety", "teach": ["Dental pain, poorly fitting dentures, dry mouth and swallowing difficulty are different problems. A person who has trouble chewing may tolerate a softer preparation; a person with swallowing impairment needs appropriate assessment. Coughing during meals, wet-sounding voice after swallowing or food seeming stuck are reasons to seek swallowing evaluation, not invitations to improvise thickened fluids.", "Do not automatically purée everything because someone is older. Unwanted texture changes may reduce enjoyment and intake, and texture safety is individual. Follow an assessed plan when one exists, and clarify uncertainty with the treating team. Acute choking or breathing difficulty requires emergency assistance, not a routine nutrition appointment."], "type": "sort", "prompt": "Choose the response supported by each observation.", "referenceSection": "l10-7", "categories": ["Appropriate professional review", "Follow assessed plan; clarify uncertainty", "Emergency assistance"], "items": [{"label": "Coughing during meals or wet-sounding voice after swallowing.", "category": 0, "feedback": "Seek prompt swallowing evaluation. Do not improvise thickened fluids or texture prescriptions."}, {"label": "An existing swallowing plan is unclear to family.", "category": 1, "feedback": "Clarify with the treating team and follow the assessed plan rather than guessing."}, {"label": "Acute choking with breathing difficulty.", "category": 2, "feedback": "Get emergency assistance immediately, not a routine nutrition appointment."}, {"label": "Poorly fitting dentures cause chewing pain.", "category": 0, "feedback": "Dental review addresses a different problem from swallowing assessment; do not automatically purée everything."}]}, {"id": "l10-interactive-10", "title": "Nourishment after bereavement", "teach": ["Sam, 78, says cooking for one feels pointless and clothes are becoming loose. Do not praise the apparent weight loss. Ask about appetite, access, grief, meal routines and the change over time, and encourage timely clinical review for unintentional loss. Offer support without attempting grief psychotherapy outside your training.", "Sam chooses a simple evening meal using familiar ingredients and wants to invite a neighbour once a week. Another person might prefer delivered meals or telephone company; there is no mandatory social solution. Discuss whether an existing family helper can assist, with Sam's consent. At follow-up, ask whether meals were eaten and enjoyed, whether shopping is manageable and whether clinical follow-up occurred. The aim is not merely a completed recipe sheet."], "type": "choice", "prompt": "Sam says cooking feels pointless and clothes have become loose. What is the best combined response?", "referenceSection": "l10-10", "options": [{"label": "Praise the weight loss and give a low-energy plan.", "feedback": "Unintentional loss should not be praised or met with restriction. It needs clinical attention.", "correct": false}, {"label": "Acknowledge the difficulty, encourage timely clinical review and ask which practical meal support Sam wants.", "feedback": "Yes. Combine assessment with chosen support such as a familiar meal, delivery or company; do not impose a social solution.", "correct": true}, {"label": "Treat the grief yourself before discussing food.", "feedback": "Offer empathy, but do not provide psychotherapy beyond your training or delay assessment of intake changes.", "correct": false}]}], "practice": {"takeaway": "What this means for my practice: support enough enjoyable food while protecting function, autonomy and clinical safety.", "ask": ["Which eating task has become harder, and what changed?", "What advice, medicines, supplements or swallowing plans are in place?", "Whom would you like involved, and what help would feel useful?"], "try": ["Address the older person directly and agree on one practical support.", "Check that meals or services are affordable, acceptable, safely stored and usable.", "Review intake, enjoyment, function and whether clinical follow-up occurred."], "refer": ["New weakness, unintentional weight loss or suspected deficiency need assessment; coughing, wet voice or food sticking need prompt swallowing evaluation.", "Acute choking or breathing difficulty requires emergency assistance; do not improvise textures or thickened fluids."], "reflection": "A family requests protein powder for new weakness. What would you ask, what can you support, and what needs assessment first?"}, "sources": [{"label": "Health Canada: healthy eating for seniors", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/life-stages/seniors.html"}, {"label": "NIA: meal planning for older adults", "url": "https://www.nia.nih.gov/health/healthy-eating-nutrition-and-diet/healthy-meal-planning-tips-older-adults"}, {"label": "EWGSOP2 consensus", "url": "https://pubmed.ncbi.nlm.nih.gov/30312372/"}, {"label": "NIA: food groups", "url": "https://www.nia.nih.gov/health/healthy-eating-nutrition-and-diet/healthy-eating-you-age-know-your-food-groups"}, {"label": "Health Canada: vitamin D", "url": "https://www.canada.ca/en/health-canada/services/nutrients/vitamin-d.html"}, {"label": "NIH: vitamin B12", "url": "https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/"}, {"label": "Québec: nutrition for older adults", "url": "https://www.quebec.ca/en/health/nutrition/healthy-eating-habits/nutrition-for-seniors"}, {"label": "ASHA: adult dysphagia", "url": "https://www.asha.org/practice-portal/clinical-topics/adult-dysphagia/"}, {"label": "Health Canada: food safety for adults 60 and over", "url": "https://www.canada.ca/en/health-canada/services/publications/food-nutrition/safe-food-handling-adults-ages-60-over.html"}]}, "lesson-11": {"title": "The Counselling Relationship", "kicker": "Make listening visible in the decisions you share.", "steps": [{"id": "l11-interactive-2", "title": "Three parts of a working relationship", "teach": ["A helping relationship is neither a lecture nor an ordinary friendship. It has a purpose, agreed roles and limits. The person seeking help brings knowledge of their life; the helper brings relevant knowledge and skills within their competence. A warm manner is useful, but warmth alone cannot compensate for a plan the person does not want or cannot use.", "Working-alliance literature distinguishes agreement about goals , agreement about tasks , and a relational bond . Research applies these concepts in particular therapeutic settings; it should not be interpreted as proof that a brief nutrition conversation produces the same outcomes as psychotherapy."], "type": "explore", "prompt": "Predict what is missing when someone likes the helper but cannot use the homework. Then compare the panels.", "referenceSection": "l11-2", "panels": [{"label": "Goals: what matters", "text": "Agreement about a valued aim differs from being agreeable. Ask whether you are working toward something the person wants."}, {"label": "Tasks: how to get there", "text": "Someone can value a goal but find homework inaccessible. Change the task instead of labelling them resistant."}, {"label": "Bond: room to disagree", "text": "Warmth matters, but so does permission to correct you. Liking a helper does not prove agreement with a plan."}]}, {"id": "l11-interactive-3", "title": "Reflect before fixing", "teach": ["Empathy means trying to understand another person's perspective and communicating that understanding. It does not require agreement with every belief, sharing the same experience or pretending certainty about feelings. Reflective listening can test an understanding: the person remains free to correct it. SAMHSA describes reflection, open questions, affirmations and summaries as central communication skills in motivational interviewing. Its guidance is written for substance-use treatment; the examples here are educational adaptations, not a treatment protocol.", "Avoid making the reflection an accusation: “You are afraid of responsibility.” That claims hidden knowledge and closes the conversation. Keep interpretations tentative, particularly when discussing shame, money, identity or family conflict."], "type": "choice", "prompt": "Someone says, “Every meal plan makes me feel like a failure.” Which reply tests your understanding?", "referenceSection": "l11-3", "options": [{"label": "This plan is easier, so you will manage it.", "feedback": "This assumes another plan is the solution before understanding the experience.", "correct": false}, {"label": "Plans have started to feel like another way to be judged. Have I understood that?", "feedback": "Yes. A tentative reflection invites correction rather than claiming hidden knowledge.", "correct": true}, {"label": "You must be afraid of responsibility.", "feedback": "That is an accusation presented as insight, not accurate curiosity.", "correct": false}]}, {"id": "l11-interactive-4", "title": "Give each listening skill a job", "teach": ["An open question invites a description: “What happens around lunch?” A closed question checks a specific fact: “Do you have a refrigerator at work?” Both can be useful; a rapid sequence of either can feel like an interview conducted for the helper's convenience.", "An affirmation identifies a genuine effort or strength: “You found a way to eat during a very unpredictable shift.” Generic praise such as “Good client!” places the helper in the role of judge. A summary selects important themes and checks whether the picture is accurate. These are skills to practise rather than scripts to deliver mechanically."], "type": "sort", "prompt": "Match each response with its main purpose.", "referenceSection": "l11-4", "categories": ["Invite a description", "Recognize genuine effort", "Gather and check themes"], "items": [{"label": "“What is different about evenings?”", "category": 0, "feedback": "An open question invites an account rather than supplying your explanation."}, {"label": "“You found a way to eat during an unpredictable shift.”", "category": 1, "feedback": "This identifies a specific effort, not a grade such as “good client.”"}, {"label": "“You want regular meals, but travel and caring duties complicate evenings. Is that right?”", "category": 2, "feedback": "A summary combines themes and invites correction."}, {"label": "“What happens around lunch?”", "category": 0, "feedback": "This invites description. A later closed question can still check a useful fact."}]}, {"id": "l11-interactive-5", "title": "Offer information without taking over", "teach": ["Autonomy means respecting the person's role in deciding what happens in their life. It is not abandonment, indifference or withholding relevant information. Shared decision-making combines clear information with the person's values and preferences; checking understanding can include teach-back. NICE recommends presenting information accessibly and reviewing what matters to the person. This is communication guidance from a UK health-care context, not a statement of Canadian law.", "Original advice sequence: ask what the person already knows, request permission to offer information, explain one relevant point, then ask how it fits their situation. “Would a few lunch options be useful?” leaves room for no. If the person declines, clarify whether another concern is more important. Do not turn every conversation into an attempt to obtain the answer you prefer."], "type": "choice", "prompt": "A person has not requested advice yet. Which sequence best preserves choice?", "referenceSection": "l11-5", "options": [{"label": "Give the full plan, then ask for agreement.", "feedback": "Agreement after a lecture is not shared decision-making. The plan may solve the wrong problem.", "correct": false}, {"label": "Avoid all information so the person decides alone.", "feedback": "Autonomy is not abandonment. Offer relevant information accessibly and with permission.", "correct": false}, {"label": "Ask what they know, request permission, offer one point and ask how it fits.", "feedback": "Yes. Connect information to values and circumstances, with room to decline or redirect.", "correct": true}]}, {"id": "l11-interactive-6", "title": "Consent has a specific purpose", "teach": ["Explain the nature of the service, the helper's actual qualifications, expected activities, costs where relevant, privacy arrangements and limits. Make space for questions, disagreement and withdrawal. CCPA's ethics code emphasizes autonomy, competence, informed consent and confidentiality; it applies to its members and must be considered alongside relevant laws and professional requirements. It is not a universal licence to practise.", "In an original nutrition-education scenario, consent to discuss meal routines does not automatically authorize contacting family, recording a session or sharing a food diary. Ask separately when the purpose or audience changes. A signature can document part of a process, but it does not establish that information was understood or participation was voluntary."], "type": "sort", "prompt": "The person agreed only to discuss meal routines. Sort the next action.", "referenceSection": "l11-6", "categories": ["Within the agreed conversation", "Requires separate permission", "Must not promise"], "items": [{"label": "Ask a relevant question about meal timing.", "category": 0, "feedback": "Stay within the purpose and remain responsive if the person wants to stop."}, {"label": "Email the food diary to a family member.", "category": 1, "feedback": "Consent to conversation is not consent to share private material."}, {"label": "Record the session for training.", "category": 1, "feedback": "A new use requires explanation and permission, alongside applicable policy."}, {"label": "Guarantee secrecy in every circumstance.", "category": 2, "feedback": "Explain actual confidentiality limits using verified organizational and professional guidance."}]}, {"id": "l11-interactive-7", "title": "Cultural humility changes the plan", "teach": ["Cultural humility is ongoing self-reflection about personal and systemic biases; cultural safety concerns respectful engagement and addressing power imbalances, with the experience of the recipient central. These are not achieved by memorizing stereotyped food lists for cultural groups.", "Original questions: “Which foods or traditions are important to preserve?” “Who normally decides what is cooked?” “Is there anything about previous health advice that made it hard to trust?” Ask without requiring a person to educate you about an entire community. Do your own learning and welcome correction."], "type": "explore", "prompt": "Predict the assumption in each scenario before opening its panel.", "referenceSection": "l11-7", "panels": [{"label": "Replacing a familiar meal", "text": "A helper’s familiar cuisine is not a neutral standard. Ask which foods and traditions should be preserved."}, {"label": "Recommending bulk buying", "text": "The plan assumes money, transport and storage. Polite wording does not remove structural barriers; check first."}, {"label": "A relative interpreting sensitive information", "text": "Do not assume this is preferred or privacy-safe. Discuss suitable interpreting services and the person’s preferences."}]}, {"id": "l11-interactive-8", "title": "Respond to distress without investigating trauma", "teach": ["Trauma-informed approaches emphasize safety, trust, collaboration, empowerment and choice. They do not require a nutrition educator to investigate trauma or provide trauma therapy.", "If a discussion becomes distressing, pause, acknowledge the person's experience and ask what would help them feel comfortable continuing or stopping. Do not insist on details to satisfy curiosity. Offer an appropriate referral when needs exceed competence. Immediate danger requires appropriate emergency support, not continuation of an ordinary lesson or meal-planning exercise."], "type": "choice", "prompt": "A food discussion becomes distressing. What should a trainee nutrition counsellor do?", "referenceSection": "l11-8", "options": [{"label": "Press for the full story so planning can continue.", "feedback": "The person does not owe details. Pressure removes choice and exceeds the purpose of nutrition education.", "correct": false}, {"label": "Pause, acknowledge distress and ask whether they want to continue, stop or seek appropriate support.", "feedback": "Yes. Offer choice and referral within competence. Immediate danger calls for appropriate emergency support.", "correct": true}, {"label": "Begin trauma therapy using the course’s listening skills.", "feedback": "Communication skills do not authorize trauma therapy. Maintain scope and facilitate suitable help.", "correct": false}]}, {"id": "l11-interactive-10", "title": "Repair with a changed action", "teach": ["Jordan says, “You keep telling me to cook, but I work two jobs.” The helper has offered several recipes without asking about time or equipment. A defensive response would explain why the recipes are healthy. A repair begins with ownership: “I moved to solutions before understanding your day. I'm sorry.”", "Ask what Jordan wanted from the appointment. Perhaps the priority is finding a usable meal near work, not learning to cook. Agree on a different task and check whether the change feels more useful. This original case illustrates that repairing a relationship involves changing behaviour, not merely using warmer words. Avoid demanding reassurance that the helper is still a good person."], "type": "choice", "prompt": "Jordan says, “You keep telling me to cook, but I work two jobs.” Which reply begins genuine repair?", "referenceSection": "l11-10", "options": [{"label": "The recipes are healthy, so let me explain again.", "feedback": "This defends advice without addressing the mismatch Jordan named.", "correct": false}, {"label": "I am sorry you feel that way. Reassure me we are okay.", "feedback": "This avoids ownership and makes Jordan responsible for the helper’s feelings.", "correct": false}, {"label": "I moved to solutions before understanding your day. I’m sorry. What did you want from this appointment?", "feedback": "Yes. Own the mistake, clarify the goal and change the task; warmer wording alone is not repair.", "correct": true}]}], "practice": {"takeaway": "What this means for my practice: show respect through consent, room for disagreement and willingness to change the plan.", "ask": ["What would feel useful today, and what would you prefer not to discuss?", "Have I understood your experience accurately?", "Does this next step fit, and what should we do differently?"], "try": ["Explain your actual role, consent process and privacy limits.", "Reflect before advising; request permission and use teach-back to check your explanation.", "Record relevant facts and repair mismatches by changing the task."], "refer": ["Seek qualified supervision for uncertain consent, confidentiality or boundary questions rather than inventing rules.", "Needs beyond nutrition education, coercion or distress require appropriate support; immediate danger requires emergency procedures."], "reflection": "What assumption would you acknowledge after unwanted advice, and what concrete change would show the person’s feedback mattered?"}, "sources": [{"label": "Primary qualitative study of working alliance", "url": "https://bmjopen.bmj.com/content/10/9/e036299"}, {"label": "SAMHSA: counselling style", "url": "https://www.ncbi.nlm.nih.gov/sites/books/NBK571068/"}, {"label": "NICE: shared decision-making", "url": "https://www.nice.org.uk/guidance/ng197/chapter/recommendations"}, {"label": "CCPA: Code of Ethics", "url": "https://www.ccpa-accp.ca/wp-content/uploads/2020/05/CCPA-2020-Code-of-Ethics-E-Book-EN.pdf"}, {"label": "First Nations Health Authority: cultural safety and humility", "url": "https://fnha.ca/services-and-support/culturally-grounded-care/cultural-safety-and-humility/"}, {"label": "SAMHSA: trauma-informed approaches", "url": "https://www.samhsa.gov/mental-health/trauma-violence/trauma-informed-approaches-programs"}]}, "lesson-12": {"title": "Behaviour Change Models and Theories", "kicker": "Choose the lens that fits the person—not a person to fit the theory • Supplementary learning, not the official chapter or assessment.", "steps": [{"id": "l12-interactive-1", "title": "Define the change before choosing a model", "referenceSection": "l12-2", "teach": ["A theory proposes relationships that help explain behaviour. A model simplifies a process or organizes relevant factors. An approach describes how a practitioner works. These categories overlap, but they are not interchangeable. A memorable acronym does not by itself explain causation or establish that an intervention works.", "Start by defining the behaviour. “Be healthier” is a broad aspiration; “prepare a lunch before two workdays” identifies an action and context. A health outcome, such as a laboratory result, is not itself a behaviour. Outcomes can change for reasons beyond the action being studied. Ask what the person wants before selecting a model, and remember that choosing not to change is not automatically ignorance."], "type": "choice", "prompt": "Jo maintains packed lunches but does not want to change breakfast. Which opening gives you useful information?", "options": [{"label": "“Which routine, if any, would you like to work on today?”", "feedback": "This starts with Jo’s own priority and a specific behaviour. You can then select a framework to answer an actual question.", "correct": true}, {"label": "“We need to move you out of precontemplation.”", "feedback": "This assumes breakfast must change and treats a stage as a problem to fix. Choosing no change is not automatically ignorance.", "correct": false}, {"label": "“You are in the maintenance stage, so breakfast should be easy.”", "feedback": "This turns a description of one behaviour into a global label. Lunch experience may help, but breakfast has a separate context and priority.", "correct": false}]}, {"id": "l12-interactive-2", "title": "Readiness is behaviour-specific", "referenceSection": "l12-3", "teach": ["The Transtheoretical Model, or TTM, includes stages of change together with processes of change, decisional balance and self-efficacy. Commonly taught stages are precontemplation (not intending change soon), contemplation (considering it), preparation (intending and taking preliminary steps), action (recently making the change) and maintenance (sustaining it). Some formulations include termination, where temptation is absent and confidence is high.", "Standard stage definitions often use time thresholds; they are operational definitions, not biological boundaries. A person can be maintaining one behaviour and contemplating another. Movement need not be linear; setbacks can involve revisiting earlier work. Stages are not permanent personality types."], "type": "explore", "prompt": "Predict the next useful conversation for each client before opening the panel. Who needs exploration, preparation, or troubleshooting?", "panels": [{"label": "“I am considering taking lunch.”", "text": "Explore the benefits and concerns of that specific change. A readiness label is a provisional description, not permission to withhold practical help."}, {"label": "“I bought a lunch container.”", "text": "Ask whether the person intends to try taking lunch and what preparation remains. One purchase alone does not establish the whole readiness picture."}, {"label": "“I took lunch until my shifts changed.”", "text": "Explore what changed and whether the goal still matters. Revisiting planning after a setback is not evidence of a defective personality or a strictly linear stage sequence."}]}, {"id": "l12-interactive-3", "title": "Confidence is not the same as benefit", "referenceSection": "l12-4", "teach": ["Self-efficacy is a belief about one's ability to perform a particular action under particular circumstances. It differs from an outcome expectation: believing that an action would help. Bandura identified mastery experience, observing others, verbal persuasion and interpretations of physiological or emotional states as sources of efficacy information.", "Social Cognitive Theory places personal factors, behaviour and the environment in reciprocal interaction. Learning can involve observing models, developing skills and regulating behaviour, not simply hearing facts. Self-efficacy is an important construct within this broader theory, not a synonym for the whole theory. Original contrast: “Taking lunch would help me” is an outcome expectation. “I can assemble lunch even on an early shift” expresses self-efficacy."], "type": "sort", "prompt": "Classify the main meaning of each statement, rather than assuming every difficulty is low confidence.", "categories": ["Self-efficacy", "Outcome expectation", "Resource constraint"], "items": [{"label": "“I could assemble lunch even on an early shift.”", "category": 0, "feedback": "This is confidence in performing a particular action under particular circumstances."}, {"label": "“Taking lunch would make my afternoon easier.”", "category": 1, "feedback": "This predicts a benefit; it does not tell you whether the person believes they can perform the action."}, {"label": "“There is nowhere suitable to store the food.”", "category": 2, "feedback": "This describes the environment. Encouragement does not create storage."}, {"label": "“I feel confident I could do it on weekends, but not on workdays.”", "category": 0, "feedback": "Confidence is context-specific. Explore what differs rather than offering global praise."}]}, {"id": "l12-interactive-4", "title": "Map a barrier before choosing support", "referenceSection": "l12-5", "teach": ["COM-B organizes influences on behaviour into capability, opportunity and motivation. Capability can be physical or psychological; opportunity can be physical or social; motivation can be reflective or automatic. The components interact, and behaviour can change them in return.", "COM-B is central to the Behaviour Change Wheel, which connects behavioural analysis with intervention functions and policy categories. Original application: a person does not prepare lunch. Limited food skills may concern capability; no refrigerator concerns physical opportunity; colleagues discouraging breaks concerns social opportunity; a considered preference for another meal concerns reflective motivation; an established rushed morning routine may involve automatic motivation."], "type": "sort", "prompt": "Match each clue to the most direct COM-B starting point. These are hypotheses to check with the client.", "categories": ["Capability", "Opportunity", "Motivation"], "items": [{"label": "“I have never learned how to assemble that meal.”", "category": 0, "feedback": "Skills may be the relevant capability gap; ask what the person already knows before demonstrating."}, {"label": "“I know how, but food money has run out.”", "category": 1, "feedback": "Affordability is an opportunity constraint, not evidence that more education is needed."}, {"label": "“My colleagues discourage taking breaks.”", "category": 1, "feedback": "The social setting can constrain opportunity. Individual motivation advice may miss it."}, {"label": "“That goal does not matter to me right now.”", "category": 2, "feedback": "This concerns the person’s reasons and priorities. Renegotiate rather than impose the goal."}]}, {"id": "l12-interactive-5", "title": "Listen for ownership, not just enthusiasm", "referenceSection": "l12-6", "teach": ["Self-Determination Theory, or SDT, distinguishes the quality of motivation, not merely its amount. Its basic psychological needs are autonomy, competence and relatedness. Intrinsic motivation involves doing something for its inherent interest or enjoyment.", "Extrinsic motivation involves a separable outcome, but can become more personally endorsed through internalization. Autonomous motivation therefore does not mean that every useful action must be enjoyable. Original comparison: “I pack lunch because my coach will shame me otherwise” expresses pressure. “I pack lunch because it helps me manage my afternoon and save money” expresses personally valued reasons, even if preparing it is not fun."], "type": "explore", "prompt": "Predict which response supports autonomy without withdrawing help. Open all three possible counsellor responses.", "panels": [{"label": "Pressure: “You must prove you care.”", "text": "This makes belonging or approval conditional on compliance. Pressure may produce agreement without personally endorsed reasons."}, {"label": "Abandonment: “Autonomy means doing it alone.”", "text": "Autonomy means choice, not isolation. A person can freely choose practical family or professional support."}, {"label": "Partnership: “What would make this worthwhile for you?”", "text": "This explores personally valued reasons. Preparing lunch need not be enjoyable in itself if the person values the result and can make a genuine choice."}]}, {"id": "l12-interactive-6", "title": "Respond to ambivalence without a persuasion trick", "referenceSection": "l12-7", "teach": ["Motivational interviewing, or MI, is a collaborative, goal-oriented communication approach that pays attention to a person's own language about change. It is particularly concerned with exploring ambivalence and strengthening personally endorsed motivation. Partnership, acceptance, compassion and evocation are central; it is not a trick for making someone agree.", "MI can be informed by theories without being identical to TTM, SCT, COM-B or SDT. A stage label does not tell you everything about how to conduct an MI conversation, and using open questions alone does not establish MI proficiency. Training, feedback and attention to the actual interaction matter."], "type": "choice", "prompt": "Bea says, “I want calmer meals, but my family’s strict menu makes everything worse.” Choose the next turn.", "options": [{"label": "“Your family means well, so follow the menu for a month.”", "feedback": "This sides with an imposed plan before exploring Bea’s priorities. Good intentions do not establish fit or consent.", "correct": false}, {"label": "“Part of you wants calmer meals, and more rules feel like the opposite. What would you choose to work on?”", "feedback": "This acknowledges ambivalence and invites Bea’s own direction. It demonstrates a collaborative move without claiming that one phrase establishes MI proficiency.", "correct": true}, {"label": "“I will ask open questions until you agree to the menu.”", "feedback": "Open questions are not ethical persuasion devices. Motivational interviewing is not a method for manufacturing agreement.", "correct": false}]}, {"id": "l12-interactive-7", "title": "Turn a framework into a testable next step", "referenceSection": "l12-10", "teach": ["MAP the specific behaviour, the person's priorities and the likely barriers. TRY one jointly chosen, feasible action linked to a clear hypothesis. LEARN from what happened, including changed circumstances and unintended effects.", "This is an original study cue, not a named validated intervention. Describe a fallback before the experiment: “If the early shift changes, what option would still feel realistic?” A lapse is information, not proof of a defective character. Review without demanding a perfect streak. Sometimes the best revision is smaller; sometimes it is environmental; sometimes the person chooses another goal."], "type": "choice", "prompt": "Ari wants lunch but lacks a refrigerator. What is the strongest MAP–TRY–LEARN plan?", "options": [{"label": "Teach the five stage names before discussing food access.", "feedback": "Knowing labels does not address the immediate constraint. Theory should organize help, not delay it.", "correct": false}, {"label": "Assign a confidence score and promise lunch success once it rises.", "feedback": "Confidence is not equipment, and no framework guarantees an individual result. The barrier needs a practical check.", "correct": false}, {"label": "Ask about actual food access and storage, jointly choose a feasible trial, then review access and acceptability.", "feedback": "This connects an opportunity hypothesis with a chosen action and a useful review. MAP–TRY–LEARN is a study cue, not a validated treatment.", "correct": true}]}], "practice": {"takeaway": "What this means for my practice: name the behaviour and barrier before choosing a theory or offering advice.", "ask": ["What change, if any, matters to you now?", "Is the obstacle confidence, skill, resources, pressure, or something else?", "What would tell us that a small trial was useful?"], "try": ["Describe one behaviour in a specific context.", "Link one chosen support to an explicit barrier hypothesis.", "Review what happened without turning a lapse into a character judgment."], "refer": ["Seek supervision when a framework is being used beyond your training or as a substitute for assessment.", "Offer appropriate practical services or qualified clinical care when the barrier exceeds your role."], "reflection": "Think of a plan you might have called “low motivation.” What alternative explanation would you check first, and how would that change your response?"}, "sources": [{"label": "Prochaska and Velicer: original model paper", "url": "https://pubmed.ncbi.nlm.nih.gov/10170434/"}, {"label": "Prochaska and Velicer: full paper", "url": "https://sdlab.fas.harvard.edu/sites/g/files/omnuum5291/files/sdlab/files/prochaska_1997_transtheoretical_model_of_health_behaviour_change.pdf"}, {"label": "Bandura: foundational self-efficacy paper", "url": "https://longevity.stanford.edu/self-efficacy-toward-a-unifying-theory-of-behavior-change/"}, {"label": "National Cancer Institute: health communication planning guide", "url": "https://www.cancer.gov/publications/health-communication/pink-book.pdf"}, {"label": "Michie, van Stralen and West: original paper", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3096582/"}, {"label": "Ryan and Deci: foundational paper", "url": "https://www.selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf"}, {"label": "MINT: understanding motivational interviewing", "url": "https://motivationalinterviewing.org/understanding-motivational-interviewing"}, {"label": "MINT: understanding MI", "url": "https://motivationalinterviewing.org/sites/default/files/understanding_mi_aug_2019.pdf"}, {"label": "Primary randomized trial", "url": "https://pubmed.ncbi.nlm.nih.gov/32393214/"}]}, "lesson-13": {"title": "Communication Skills", "kicker": "Listen, check, and respond in a conversation that can change direction • Supplementary learning, not the official chapter or assessment.", "steps": [{"id": "l13-interactive-1", "title": "Hear the problem before solving it", "referenceSection": "l13-2", "teach": ["A technically accurate explanation can still be unhelpful if the client feels judged, cannot understand it, or cannot use it. Effective counselling therefore involves listening for meaning, checking understanding, and agreeing what happens next. The aim is not to win an argument about food.", "It is to help someone make an informed, workable decision while preserving their autonomy. Consider the difference between “You need to stop skipping lunch” and “What happens around lunchtime on a workday?” The first assumes both the problem and its solution. The second opens space for information: perhaps breaks are unpredictable, food storage is unavailable, nausea makes eating uncomfortable, or the client is deliberately restricting."], "type": "choice", "prompt": "Maya says, “Everyone tells me to cook. I am exhausted.” What is the best opening?", "options": [{"label": "“Batch cooking is the obvious solution.”", "feedback": "This repeats the unrequested cooking agenda before learning whether time, facilities, energy, or another issue matters.", "correct": false}, {"label": "“More cooking sounds like more work when you are already stretched.”", "feedback": "This reflects the expressed concern and gives Maya room to confirm or correct it. Useful problem-solving can follow the actual barrier.", "correct": true}, {"label": "“So you do not want to improve your eating.”", "feedback": "This infers motivation from a complaint about workload and risks shutting down relevant information.", "correct": false}]}, {"id": "l13-interactive-2", "title": "Choose a communication tool deliberately", "referenceSection": "l13-3", "teach": ["OARS stands for open questions, affirmations, reflective listening, and summaries. SAMHSA describes these core motivational interviewing skills within substance-use treatment. Their communication principles can inform nutrition conversations, but this lesson is not training or certification in delivering a complete motivational interviewing intervention.", "An open question invites explanation: “What would you like to feel different after our work together?” A closed question obtains a particular detail: “Do you have access to a refrigerator?” Both are useful. Open questions discover the story; focused questions clarify it. Asking only open questions can leave safety details unclear; asking only closed questions can feel like an interrogation."], "type": "sort", "prompt": "Classify each response by its main function. An affirmation recognizes a specific effort; a reflection offers understanding; a summary gathers threads.", "categories": ["Affirmation", "Reflection", "Summary"], "items": [{"label": "“You found a way to eat during an unpredictable shift.”", "category": 0, "feedback": "This identifies an actual effort rather than praising obedience."}, {"label": "“Meal preparation feels like another job.”", "category": 1, "feedback": "This offers an understanding for the client to confirm or correct."}, {"label": "“Time is tight, lunch is available nearby, and cost matters. What did I miss?”", "category": 2, "feedback": "This gathers several relevant threads and invites correction."}, {"label": "“You noticed the difficulty and brought it up today.”", "category": 0, "feedback": "The affirmation is grounded in something the person actually did."}]}, {"id": "l13-interactive-3", "title": "Follow three possible turns", "referenceSection": "l13-4", "teach": ["A simple reflection stays near the words: “You feel rushed in the morning.” A more complex reflection tentatively connects meaning: “Having breakfast ready might make mornings feel less chaotic.” More complex does not automatically mean better.", "If your interpretation is unsupported, use a tentative phrase or return to a simpler reflection. Compare three responses to “I know what to do, but I never keep it up.” Advice-first: “Set an alarm.” Judgment: “You need discipline.” Reflective: “You have tried before, and you are discouraged that the plans have not lasted.” The reflective response does not solve the problem immediately."], "type": "explore", "prompt": "Dev says, “I am not giving up my family’s food.” Predict what each response may open or close before revealing it.", "panels": [{"label": "Defend the advice", "text": "“But my plan is healthier.” This moves into debate and misses Dev’s concern about identity. More information may not resolve a concern that advice feels dismissive."}, {"label": "Reflect too confidently", "text": "“You are afraid your family will reject you.” This adds a meaning Dev has not supplied. If it misses, accept correction rather than defending the interpretation."}, {"label": "Reflect and invite", "text": "“Keeping family meals matters, and you worry this means losing them. What would you actually like help with?” Dev can clarify the concern and identify a different priority."}]}, {"id": "l13-interactive-4", "title": "Ask–offer–check, without a hidden agenda", "referenceSection": "l13-5", "teach": ["Information is often more useful when it answers a question the client actually has. An original teaching sequence is ask–offer–check: ask what they know and whether information would help; offer a small relevant explanation; check what they make of it.", "This is a study sequence, not a validated assessment tool. For example: “What have you heard about fibre?” Then: “Would a short explanation help?” After a brief explanation: “How does that fit with foods you enjoy?” Do not treat asking permission as a trick to secure agreement. Someone may decline, ask for another topic, or disagree after hearing the information."], "type": "choice", "prompt": "Maya confirms that recipes are not the problem. She asks for low-preparation ideas. What do you say?", "options": [{"label": "“I cannot give information because good counselling only uses questions.”", "feedback": "Collaborative communication does not mean withholding a requested, appropriate explanation within your competence.", "correct": false}, {"label": "“Here are twenty options and a full nutrient lecture.”", "feedback": "An information flood may obscure the decision she wants to make. Start with a small relevant amount in a usable format.", "correct": false}, {"label": "“Would comparing two familiar options help? Then we can see which fits your breaks.”", "feedback": "This offers relevant information after understanding the request and leaves the choice open. Asking permission does not require her to agree afterward.", "correct": true}]}, {"id": "l13-interactive-5", "title": "Check your explanation—not the client’s obedience", "referenceSection": "l13-6", "teach": ["Teach-back asks a person to explain the plan in their own words so you can identify communication gaps. It should be framed as a check on how clearly you explained, not as a memory examination. If understanding is incomplete, explain differently and check again.", "An original example: “I covered several things quickly. To check that I explained them clearly, how would you describe the lunch experiment we agreed?” If the person describes a different plan, avoid “No, you weren't listening.” Try “I can see I made that confusing. Let's make the plan simpler.” Teach-back is different from asking “Do you understand?” People may say yes out of politeness or embarrassment."], "type": "choice", "prompt": "Maya describes a different shopping day from the one you thought was agreed. Choose your next response.", "options": [{"label": "“I may have made that confusing. Let’s clarify what fits, then you can describe the plan in your own words.”", "feedback": "This takes responsibility for clarity and checks a workable shared understanding. Maya can understand a plan and still choose to change it.", "correct": true}, {"label": "“You said you understood, so the explanation is finished.”", "feedback": "A yes/no understanding check can hide confusion. The mismatch is useful information, not something to ignore.", "correct": false}, {"label": "“No, you were not listening. Repeat my plan exactly.”", "feedback": "Teach-back is not a memory test or a demand for compliance. This response makes a communication gap the client’s fault.", "correct": false}]}, {"id": "l13-interactive-6", "title": "Make disagreement useful", "referenceSection": "l13-7", "teach": ["Shared decision-making connects available options with what matters to the person. Discuss relevant benefits, burdens, uncertainties, and the option of no change where appropriate; agree how the decision will be reviewed. In an original nutrition example, the options might be preparing food at home, assembling convenience foods, or buying lunch. These are not ranked by moral worth.", "Compare cost, time, facilities, enjoyment, and reliability. Ask “Which would fit your next week?” rather than “Which is the healthiest choice?” when the latter hides practical trade-offs. If disagreement emerges, slow down. “We may be looking at this differently. What feels unhelpful about my suggestion?”"], "type": "explore", "prompt": "Predict which next turn preserves both accuracy and autonomy. Compare these endings to a discussion of lunch options.", "panels": [{"label": "“The home-cooked option wins.”", "text": "This ranks options without checking cost, time, facilities, or preference. A technically appealing option can still be impractical."}, {"label": "“Whatever you read online must be right for you.”", "text": "Rapport does not require endorsing unsafe or unsupported claims. Explain uncertainty respectfully and seek qualified input when needed."}, {"label": "“What feels unhelpful about my suggestion?”", "text": "This makes room for correction. Compare genuine trade-offs, acknowledge uncertainty, and agree whether to try something, gather information, or make no change."}]}], "practice": {"takeaway": "What this means for my practice: a useful conversation leaves the client understood, informed, and able to correct the plan.", "ask": ["What would make today’s conversation useful?", "Would a short explanation help, and what format works for you?", "How would you describe the next step, so I can check that I explained it clearly?"], "try": ["Separate what was said from what you inferred.", "Practise one grounded affirmation, reflection, and summary in a role-play.", "Invite correction and change the plan when the correction matters."], "refer": ["Use appropriate interpretation or accessibility support rather than assuming apparent agreement means understanding.", "Refer questions requiring diagnosis, prescribing, or psychotherapy to appropriately qualified professionals."], "reflection": "Rewrite one advice-first response as a reflection followed by a genuine invitation. What new information could the revised response reveal?"}, "sources": [{"label": "SAMHSA TIP 35, chapter 3", "url": "https://www.ncbi.nlm.nih.gov/books/NBK571068/"}, {"label": "AHRQ teach-back", "url": "https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/teachback.html"}, {"label": "NICE shared decision-making guidance", "url": "https://www.nice.org.uk/guidance/ng197/chapter/recommendations"}]}, "lesson-14": {"title": "The Counselling Interview", "kicker": "Navigate an interview with signposts, not an interrogation • Supplementary learning, not the official chapter or assessment.", "steps": [{"id": "l14-interactive-1", "title": "Set up a safe conversation", "referenceSection": "l14-3", "teach": ["Before the meeting, confirm the purpose, available time, accessibility needs, and any information already provided. Do not make the client repeat a long history simply because you have not reviewed authorized records. Equally, do not treat an old record as automatically accurate. Ask what has changed. Consider privacy in both physical and remote settings.", "Can others hear the conversation? Is the client comfortable speaking where they are? Use approved systems rather than improvising with personal accounts or recordings. Do not record sessions by default. Any recording requires the relevant permission, secure arrangements, and compliance with applicable rules."], "type": "explore", "prompt": "Before opening each setting, predict what you would check before starting the interview.", "panels": [{"label": "Remote appointment in a shared room", "text": "Ask whether the client can speak comfortably and privately. Use approved systems and consider alternatives if the setting is unsuitable; do not record by default."}, {"label": "A support person joins", "text": "Ask whether the client wants that involvement and clarify what may be discussed. Presence does not automatically grant unrestricted permission."}, {"label": "The client expects medical answers", "text": "Explain your actual role and who can address medical questions. Describe applicable confidentiality limits without promising absolute secrecy."}]}, {"id": "l14-interactive-2", "title": "Negotiate the agenda", "referenceSection": "l14-4", "teach": ["A warm opening need not be elaborate. Confirm how the person wishes to be addressed and whether any communication adjustments would help. Ask what brought them and what would make the appointment useful. If someone else referred them, distinguish the referrer's concern from the client's own priorities.", "NICE recommends agreeing an agenda and making the available discussion time clear. It also emphasizes the person's preferences for involvement in decisions. An original opening might be: “We have about forty minutes. I would like to understand your routine, hear what you want help with, and leave time for a next step. What would you put first?”"], "type": "choice", "prompt": "Lena’s referral says “weight management.” She says, “I want to get through work without being distracted by hunger.” Choose your opening.", "options": [{"label": "“That hunger proves your blood sugar is abnormal.”", "feedback": "An interview report does not establish a medical diagnosis. Clarify the experience and arrange assessment when appropriate.", "correct": false}, {"label": "“The referral determines the goal, so we must start with weight.”", "feedback": "The referral provides context, not automatic consent. Lena’s priority needs to be heard alongside relevant safety considerations.", "correct": false}, {"label": "“Let’s start with what happens during work. We can agree what is useful today and flag anything needing separate assessment.”", "feedback": "This respects Lena’s agenda without abandoning safety or scope. A shared agenda guides the interview better than an imposed label.", "correct": true}]}, {"id": "l14-interactive-3", "title": "Separate reports from conclusions", "referenceSection": "l14-5", "teach": ["Begin broadly: “Walk me through a fairly typical day.” Follow with “How was yesterday different?” A single day may be unusual, so learn about variability across workdays, weekends, caregiving demands, and available money. Ask what already works. An assessment that records only deficits misses resources the eventual plan could use.", "Relevant areas may include meal timing, food access, cooking facilities, preferences, cultural or religious practices, symptoms, relevant diagnosed conditions, and medicines or supplements. Ask only for information relevant to your role and purpose. The presence of a topic on a template does not justify intrusive questioning."], "type": "sort", "prompt": "Place each note in the correct category before building a plan.", "categories": ["Client report", "Unsupported conclusion", "Useful clarification"], "items": [{"label": "“Client reports nausea after breakfast on three mornings.”", "category": 0, "feedback": "This records the person’s account without asserting a cause."}, {"label": "“Breakfast causes the nausea.”", "category": 1, "feedback": "Timing alone does not establish causation or authorize diagnosis."}, {"label": "“How was yesterday different from a usual workday?”", "category": 2, "feedback": "This explores variability rather than treating one day as a full baseline."}, {"label": "“Missed lunch means low motivation.”", "category": 1, "feedback": "A missed meal can reflect access, scheduling, symptoms, priorities, or other factors."}]}, {"id": "l14-interactive-4", "title": "Offer a reason and an exit", "referenceSection": "l14-6", "teach": ["Sensitive areas can include finances, weight experiences, restriction, body image, alcohol, family conflict, and mental health. Explain relevance in neutral language: “Food costs can affect what plans are realistic. Would it be okay to ask whether your budget regularly covers enough food?” Avoid implying that financial difficulty is a personal failure. Do not require disclosure beyond what is necessary for safe service.", "A client can decline a question. Explain if that missing information limits the advice you can responsibly provide. Offer another way of discussing it, another appointment, or an appropriate referral where helpful. If someone becomes distressed, pause the information gathering."], "type": "choice", "prompt": "Amir becomes quiet: “I do not want to discuss what happens at home.” What is the best next turn?", "options": [{"label": "“We can pause. Is there anything that changes what would feel safe or practical to plan, without going into details?”", "feedback": "This respects a boundary and focuses on relevant planning needs. Follow applicable safety procedures if an immediate concern emerges.", "correct": true}, {"label": "“I promise nothing you say could ever be shared.”", "feedback": "Absolute secrecy may misrepresent applicable confidentiality limits. Explain the actual rules of the setting accurately.", "correct": false}, {"label": "“I need every detail before I can help.”", "feedback": "More disclosure is not automatically a better interview. Explain relevant limits without demanding unnecessary sensitive detail.", "correct": false}]}, {"id": "l14-interactive-5", "title": "Choose the appropriate interview outcome", "referenceSection": "l14-7", "teach": ["A useful midpoint summary includes the person's goal, the main circumstances, existing strengths, uncertainties, and possible safety needs. Say “Let me check that I have this right,” then invite correction. This reduces the risk of building an elaborate plan around a mistaken assumption. Motivational interviewing literature warns against premature focus: moving into a change agenda before establishing a working relationship and understanding the person's priorities.", "Distinguish three possible findings. First, there may be enough information to discuss a low-risk practical experiment. Second, you may need another detail before choosing a plan. Third, the issue may need a different professional."], "type": "sort", "prompt": "Match the situation to the next kind of work; not every interview should end with a new eating goal.", "categories": ["Practical experiment", "Clarify first", "Appropriate professional input"], "items": [{"label": "The client chooses a feasible lunch option and access is understood.", "category": 0, "feedback": "There may be enough information for a low-risk, jointly chosen practical trial within your role."}, {"label": "It is unclear whether any food storage is available.", "category": 1, "feedback": "Resolve the detail that determines whether the proposed action is workable."}, {"label": "The client asks you to diagnose the cause of recurring symptoms.", "category": 2, "feedback": "Do not convert an interview into a diagnosis. Explain your role and the appropriate assessment pathway."}, {"label": "The client says the old record no longer reflects their medicines.", "category": 1, "feedback": "Clarify the relevant current information through appropriate channels; do not independently alter treatment."}]}, {"id": "l14-interactive-6", "title": "Close the loop", "referenceSection": "l14-8", "teach": ["Leave time to agree what happens next. Ask what the client wants to try, what might make it difficult, and what support is needed. If no behavioural change is chosen, the next step could be gathering information, arranging a referral, or returning to a decision later.", "Give a short summary in an accessible format. Use teach-back to check your explanation, not to test obedience. For example: “You will choose two workdays to try the lunch option. I will send our short list through the approved system. Next week we will review what was easy and what got in the way. How would you describe that plan?”"], "type": "choice", "prompt": "You have two minutes left. Lena chose one lunch trial and you offered to send a short list. Which ending is most useful?", "options": [{"label": "“Great, just eat better and book again sometime.”", "feedback": "This loses the agreed action, responsibilities, and review. A positive tone does not replace a clear next step.", "correct": false}, {"label": "“You choose the two workdays; I send the list through our approved system. Next week we review access and ease. How would you describe the plan?”", "feedback": "This clarifies who does what and why follow-up matters, then checks your explanation. Document the actual agreement promptly.", "correct": true}, {"label": "“I will record that you accepted the referral’s full programme.”", "feedback": "Only record consent and actions actually agreed. One practical trial is not consent to a different programme.", "correct": false}]}], "practice": {"takeaway": "What this means for my practice: structure the interview around purpose, consent, context, and an understood next step.", "ask": ["What would you put first in our time today?", "What has changed since the information already recorded?", "What would make this plan feel safe and practical?"], "try": ["Explain your role, available time, and applicable confidentiality limits.", "Alternate relevant questions with reflections and a correction-inviting summary.", "Close with responsibilities, review arrangements, and a clear record of the actual agreement."], "refer": ["Use your setting’s emergency pathway for an immediate safety concern rather than continuing the routine agenda.", "Seek supervision or qualified assessment when symptoms or sensitive needs exceed your competence."], "reflection": "Rehearse a ten-minute interview. Which question could you remove, and which missing clarification would most improve the next step?"}, "sources": [{"label": "NICE shared decision-making guidance", "url": "https://www.nice.org.uk/guidance/ng197/chapter/recommendations"}, {"label": "SAMHSA TIP 35, chapter 3", "url": "https://www.ncbi.nlm.nih.gov/books/NBK571068/"}, {"label": "AHRQ teach-back", "url": "https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/teachback.html"}]}, "lesson-15": {"title": "Developing a Nutritional Care Plan", "kicker": "Build a plan that fits a real week—and can be revised • Supplementary learning, not the official chapter or assessment.", "steps": [{"id": "l15-interactive-1", "title": "Start with a useful baseline", "referenceSection": "l15-3", "teach": ["Ask “What would you most like this plan to help with?” Possible answers include more reliable meals, less stress about shopping, support following advice from a treating clinician, or greater confidence preparing familiar foods. Do not automatically substitute your preferred outcome. A baseline describes the present situation in enough detail to guide a decision.", "For a lunch-access goal, useful information might include the number of workdays with a break, food facilities, usual purchases, budget, and what the client considers satisfying. A comprehensive food diary is not always necessary. Choose the least burdensome information that answers the question."], "type": "choice", "prompt": "Jo says, “I want less chaotic evenings.” Which question most directly starts a relevant plan?", "options": [{"label": "“Can you track every food and nutrient for a month first?”", "feedback": "A detailed diary is not automatically necessary. Choose the least burdensome information that answers the planning question.", "correct": false}, {"label": "“Will you agree to cook every night?”", "feedback": "This selects a demanding solution before understanding Jo’s routine, resources, or definition of less chaotic.", "correct": false}, {"label": "“Which evenings are hardest, and what already works on the others?”", "feedback": "This connects the stated priority to variability and existing strengths. It can reveal a small action that fits rather than rebuilding everything.", "correct": true}]}, {"id": "l15-interactive-2", "title": "Triage the planning work", "referenceSection": "l15-4", "teach": ["Not every issue deserves equal attention today. Separate urgent clinical concerns from practical goals that can safely be explored. If concerning symptoms, major restriction, or a possible medicine-related problem emerges, arrange the appropriate professional input rather than hiding it inside an ordinary meal-planning task.", "Do not independently stop or adjust prescribed medicines. For nonurgent choices, discuss which issue matters most and which change seems feasible. A useful original prompt is “Which change would make the biggest useful difference without overwhelming the week?” Sometimes stabilizing access to enough food is more appropriate than optimizing variety. Sometimes the first step is understanding a clinician's instructions rather than adding new advice."], "type": "sort", "prompt": "Choose the main next step in each situation. Safety and scope come before adding goals.", "categories": ["Explore a practical goal", "Clarify feasibility", "Arrange qualified input"], "items": [{"label": "A client asks you to stop a prescribed medicine.", "category": 2, "feedback": "Do not independently alter medicines. Help direct the question to the appropriate treating professional."}, {"label": "Jo chooses two low-preparation dinners using familiar foods.", "category": 0, "feedback": "This is a focused practical option if it fits the assessment and your role."}, {"label": "The plan requires a second shopping trip, but transport is unknown.", "category": 1, "feedback": "Check access before calling the goal achievable."}, {"label": "A client wants a strict elimination diet for unexplained symptoms.", "category": 2, "feedback": "Do not diagnose intolerance from a diary or invent a therapeutic restriction protocol; appropriate clinical assessment is needed."}]}, {"id": "l15-interactive-3", "title": "Compare genuine options", "referenceSection": "l15-5", "teach": ["For a practical problem there may be several acceptable options. If breakfast is difficult, possibilities might include preparing something the night before, choosing a portable food, eating at a different point in the morning, or first investigating symptoms that interfere with eating. The options are not interchangeable for every person.", "Shared decision-making involves considering choices alongside what matters to the person and recording the decision and its relevant preferences. For each option, discuss likely usefulness, burden, cost, enjoyment, and uncertainty. Do not present a possibility as guaranteed to improve symptoms. “This could help us test whether having food available changes the afternoon pattern” is more accurate than “This will cure your tiredness.” Explain when medical assessment should occur independently of the experiment."], "type": "explore", "prompt": "Predict which trade-off could change Jo’s choice before opening each option. No option wins solely because it sounds more virtuous.", "panels": [{"label": "Cook from scratch each evening", "text": "Explore time, enjoyment, energy, equipment, and costs. This may suit some people but conflicts with Jo’s description of two particularly difficult evenings."}, {"label": "Use familiar low-preparation dinners", "text": "This may fit the existing shopping routine and reduce work. Check whether the meals are acceptable and accessible rather than assuming convenience solves everything."}, {"label": "Pause a new food goal", "text": "A pause may be appropriate if access, symptoms, or another priority needs attention. Choosing no immediate dietary change is not automatically a failed appointment."}]}, {"id": "l15-interactive-4", "title": "Draft a flexible goal", "referenceSection": "l15-6", "teach": ["SMART is commonly expanded as specific, measurable, achievable, relevant, and time-bound. Variants exist. Here it is a drafting aid, not a validated treatment or a rule that every meaningful goal must be reduced to a number.", "“Eat better” is too vague to guide action. An original version could be: “For the next seven days, I will put one familiar lunch option in my work bag on Monday and Thursday evenings, then review whether it was practical.” The goal identifies an action, context, and review period. It does not promise a health outcome. Measurable need not mean calories, weight, or exhaustive tracking."], "type": "choice", "prompt": "Which goal best turns Jo’s priority into an agreed, reviewable experiment?", "options": [{"label": "“Be healthier and never miss a home-cooked dinner.”", "feedback": "This combines a vague outcome with an absolute demand. It does not describe a realistic, flexible action or useful review.", "correct": false}, {"label": "“At the usual shop, choose ingredients for two familiar easy dinners next week; review stress, ease, and enjoyment afterward.”", "feedback": "This specifies an action, context, and review tied to Jo’s own purpose. Measurement does not need to mean calories, weight, or exhaustive tracking.", "correct": true}, {"label": "“Cook every night until your stress is cured.”", "feedback": "This promises an outcome and ignores the baseline. A routine trial cannot guarantee a cure or establish the cause of distress.", "correct": false}]}, {"id": "l15-interactive-5", "title": "Give the plan a backbone", "referenceSection": "l15-7", "teach": ["A goal names what the person wants to do. An action plan specifies when, where, and how. A coping plan addresses predictable barriers. NICE's behaviour-change guidance includes collaboratively chosen goals, action planning, monitoring, and plans for setbacks.", "For example, buy two familiar lunch options during the usual shop and place a reminder beside the work bag. If the planned food is unavailable, use an affordable purchased option identified beforehand. Review cost, convenience, and satisfaction. The backup is not a lesser moral choice; it makes the plan resilient. Ask whether family support is welcome and safe before suggesting it."], "type": "sort", "prompt": "Match each planning statement to its function.", "categories": ["Action and cue", "Coping backup", "Review question"], "items": [{"label": "“Choose the two dinner options during Saturday’s usual shop.”", "category": 0, "feedback": "This says when and how the chosen action will happen."}, {"label": "“If ingredients are unavailable, use the affordable prepared option already identified.”", "category": 1, "feedback": "A realistic backup handles disruption without treating it as moral failure."}, {"label": "“Did those evenings feel less stressful, and was the food enjoyable?”", "category": 2, "feedback": "Review the original purpose and lived experience, not just task completion."}, {"label": "“Place the short shopping list beside the usual bag.”", "category": 0, "feedback": "The cue supports the action at a useful moment; it is not a guarantee."}]}, {"id": "l15-interactive-6", "title": "Record agreement, then review it honestly", "referenceSection": "l15-8", "teach": ["A practical record can use seven headings: priority, relevant assessment, agreed action, support, responsibilities, monitoring, and review. Add consent, referrals, and safety instructions as appropriate to the setting. Use professional documentation requirements if they apply; this teaching template does not replace them. Write “Client chose to try…” only when that is true.", "Separate “Options discussed” from “Action agreed.” Include why the selected option fits the person's circumstances. Record important uncertainty rather than making the note appear more certain than the conversation was. Monitoring should be proportionate. Ask what information will help decide whether to continue, change, or stop the plan."], "type": "choice", "prompt": "Jo considered several options but chose only two easy dinners. Which note best supports continuity?", "options": [{"label": "“Client needs more motivation.”", "feedback": "A character label is neither an agreed plan nor an explanation. Record the circumstances and what the person decided.", "correct": false}, {"label": "“Client committed to the complete healthy-eating plan.”", "feedback": "This overstates agreement and hides what was actually chosen. Options discussed are not the same as consented actions.", "correct": false}, {"label": "“Client chose two familiar dinners for difficult evenings; buys ingredients at usual shop; backup discussed; review stress and access next week.”", "feedback": "This records the reason, action, context, backup, and review. Add the actual responsibilities, consent, or referrals required in your setting.", "correct": true}]}], "practice": {"takeaway": "What this means for my practice: a care plan is an agreed action with a reason, support, responsibilities, and a review—not just a menu.", "ask": ["What would you most like this plan to help with?", "What would make the action feasible on a difficult day?", "What information will help us decide to continue, change, pause, or refer?"], "try": ["Use the least burdensome baseline that answers the planning question.", "Write one action, one realistic backup, and one review question with the client.", "Distinguish options discussed from actions agreed in the record."], "refer": ["Coordinate with qualified care for symptoms, major restriction, or medicine-related concerns; do not independently alter treatment.", "For a referral, agree who contacts whom and how the next step will be confirmed within consent and local rules."], "reflection": "Write a four-sentence plan for Jo. Could someone who missed the appointment identify the priority, action, backup, and review without guessing?"}, "sources": [{"label": "NICE shared decision-making guidance", "url": "https://www.nice.org.uk/guidance/ng197/chapter/recommendations"}, {"label": "NICE behaviour change: individual approaches", "url": "https://www.nice.org.uk/guidance/ph49/chapter/recommendations"}]}, "lesson-16": {"title": "Facilitating Self Management", "kicker": "Build adaptable skills without creating dependency or blame • Supplementary learning, not the official chapter or assessment.", "steps": [{"id": "l16-interactive-1", "title": "Independence can include support", "referenceSection": "l16-2", "teach": ["Self-management means participating in decisions and everyday actions that affect one's health and wellbeing. It does not mean doing everything alone, never needing help, or accepting responsibility for circumstances outside one's control. A client may manage a routine effectively with family assistance, accessible services, reminders, or professional follow-up.", "The counsellor's job is not to become the client's permanent decision-maker. It is to help the person understand choices, develop relevant skills, use available resources, and know when to seek help. Independence can include the ability to request support early. An important distinction is between self-management and self-blame."], "type": "explore", "prompt": "Predict which version develops self-management. Open each interpretation and compare what it asks of the client.", "panels": [{"label": "“You should never need help again.”", "text": "This mistakes self-management for isolation. Requesting support early can be a useful skill, especially when circumstances change."}, {"label": "“I will choose every meal for you.”", "text": "This can make the counsellor the permanent decision-maker. The aim is to build understanding and choices the person can use beyond the appointment."}, {"label": "“Let’s practise a decision you can adapt.”", "text": "This supports transferable skills while leaving room for chosen help, accessible resources, and continued professional care when needed."}]}, {"id": "l16-interactive-2", "title": "Match support to the missing piece", "referenceSection": "l16-3", "teach": ["When a plan is not happening, do not assume the explanation is unwillingness. Ask what the person understands, what they can do, what the setting permits, and whether the goal still matters.", "The same missed lunch could reflect uncertainty about what to buy, lack of storage, no break, nausea, or a decision to prioritize another concern. An original diagnostic-for-learning question—not a medical diagnostic tool—is: “Is the main difficulty knowing what, knowing how, having the opportunity, or wanting this change right now?” The answer guides the next conversation. A knowledge gap may call for a short explanation."], "type": "sort", "prompt": "Choose the most direct starting point, then check your hypothesis with the person.", "categories": ["Explain or practise", "Address opportunity", "Renegotiate the goal"], "items": [{"label": "“I have access to ingredients but do not know how to put this meal together.”", "category": 0, "feedback": "A short demonstration or practice may address the relevant skill gap."}, {"label": "“I can prepare it, but there is no reliable break.”", "category": 1, "feedback": "The setting constrains the action. More instructions do not create time at work."}, {"label": "“I want help with food costs, not meal variety.”", "category": 2, "feedback": "The proposed goal misses the person’s priority; agree what matters now."}, {"label": "“I understand the plan, but cannot afford the food.”", "category": 1, "feedback": "Explore accessible practical support rather than interpreting the problem as unwillingness."}]}, {"id": "l16-interactive-3", "title": "Make the skill reusable", "referenceSection": "l16-4", "teach": ["A self-management skill is something the person can use again: comparing realistic options, planning a shopping trip, preparing a familiar meal, explaining a question to a clinician, or adapting a routine when work changes. Choose a skill connected to the client's goal rather than assigning generic homework. Break the skill into manageable steps.", "For meal assembly, the steps might be identifying available foods, checking facilities, selecting an option, obtaining ingredients, and trying it once. Do not assume the person needs instruction at every step. Ask what they already do confidently. An experiment is different from a performance test."], "type": "choice", "prompt": "A client wants confidence choosing lunch when the usual option is unavailable. What task fits?", "options": [{"label": "Compare two available options, check cost and facilities, then rehearse choosing a backup.", "feedback": "This breaks a relevant decision into manageable steps the client can reuse. Ask which parts they already do confidently.", "correct": true}, {"label": "Require a perfect week before offering feedback.", "feedback": "A small experiment is for learning, not proving commitment. Feedback can help even when the first trial does not work.", "correct": false}, {"label": "Ask them to memorize one menu and repeat it indefinitely.", "feedback": "This gives a fixed answer but does not practise adapting when the relevant condition changes.", "correct": false}]}, {"id": "l16-interactive-4", "title": "Repair the environment, not the person", "referenceSection": "l16-6", "teach": ["Motivation varies, so the physical and social setting matters. Consider what is visible, available, affordable, and easy at the moment of action. An original example is keeping an agreed shelf space for work-lunch ingredients. Another is identifying a reliable food option near the workplace rather than relying on cooking after an exhausting shift.", "NICE's behaviour-change guidance includes attention to supportive routines, social support, coping plans, and changes to the immediate environment when maintaining behaviour. These are supports, not guarantees. Social support should be chosen by the client. A friend might help with shopping or share a meal, but monitoring, criticism, or unsolicited comments may make things harder."], "type": "choice", "prompt": "Sara says, “I stopped packing lunch when my shift moved earlier. I knew I could not keep anything up.” Choose your response.", "options": [{"label": "“Your old plan succeeded once, so it must still be the right plan.”", "feedback": "A plan can stop fitting when conditions change. Previous success is useful information, not a reason to ignore new constraints.", "correct": false}, {"label": "“Let’s double the tracking until your willpower returns.”", "feedback": "This assumes a motivation deficit and adds burden without addressing the removed cue or changed schedule.", "correct": false}, {"label": "“That change disrupted something that had worked. Where could lunch fit now, and what storage is actually available?”", "feedback": "This reflects disappointment and investigates the environment. Sara can choose a new cue, location, or practical backup rather than being graded on willpower.", "correct": true}]}, {"id": "l16-interactive-5", "title": "Notice when monitoring becomes harmful", "referenceSection": "l16-7", "teach": ["Monitoring is useful only if it informs a decision. A daily check mark may answer whether a routine happened. A short note about the barrier may explain why it did not. Detailed tracking of every food, symptom, and emotion may be unnecessary and can become intrusive.", "Agree what will be observed, how often, who will see it, and when it will stop or change. Ask whether monitoring has caused distress in the past. If it increases preoccupation or shame, reassess rather than insisting that more data are always better. Use feedback descriptively. “Lunch happened on the two days when the food was already at work” is more useful than “You were only fifty percent compliant.” The descriptive version suggests an environmental solution."], "type": "choice", "prompt": "Eli says, “The diary makes me anxious. I avoid foods I cannot record precisely.” What should happen next?", "options": [{"label": "Take the concern seriously, reassess the diary, and arrange appropriately qualified support for concerning distress or restriction.", "feedback": "The tool should serve the person, not become the goal. Stay within your role, consider a lower-burden alternative if appropriate, and coordinate care with consent.", "correct": true}, {"label": "Diagnose an eating disorder and begin psychotherapy yourself.", "feedback": "Recognizing a concern does not authorize diagnosis or psychological treatment. Explain your limits and use an appropriate referral pathway.", "correct": false}, {"label": "Praise the precision and add more tracking fields.", "feedback": "Increasing restriction and distress should not be treated as dedication. More data are not automatically safer or more useful.", "correct": false}]}, {"id": "l16-interactive-6", "title": "Rehearse a difficult-day recovery", "referenceSection": "l16-8", "teach": ["A lapse is a departure from a chosen plan, not evidence of a defective character. Avoid interpreting one difficult day as proof that nothing has changed. Equally, do not dismiss a recurring difficulty with empty reassurance. Investigate the pattern. An original recovery sequence is notice, understand, adjust, reconnect.", "Notice what happened without moral labels. Understand the circumstances and the person's response. Adjust the plan or support. Reconnect with the chosen next step or relevant professional help. This is a study sequence, not a validated clinical relapse-prevention treatment. Use an if–then backup: “If the shift changes and I cannot shop, then I will use the agreed cupboard option.” A backup should be realistic and safe."], "type": "explore", "prompt": "The chosen shopping trip falls through. Predict which backup supports learning rather than punishment, then compare the three paths.", "panels": [{"label": "Punish the lapse", "text": "“Skip the next meal to make up for it.” A backup should not introduce compensatory restriction or an increasingly rigid set of rules."}, {"label": "Ignore the pattern", "text": "“It does not matter; just try harder next time.” Empty reassurance misses repeated barriers and does not help the person make a workable decision."}, {"label": "Notice, understand, adjust, reconnect", "text": "Describe what happened, ask what changed, choose a realistic backup or pause, and reconnect with support. This is an original study sequence, not a clinical relapse-prevention treatment."}]}], "practice": {"takeaway": "What this means for my practice: support a skill the client can adapt, with a realistic backup and permission to seek help.", "ask": ["At what point does the plan become difficult?", "If the usual option is unavailable, what would your backup be?", "Does this monitoring help you decide, or does it add pressure?"], "try": ["Practise one transferable decision using the client’s actual resources.", "Choose the least burdensome observation that informs a review.", "Agree follow-up and how to seek help earlier without promising constant availability."], "refer": ["Arrange qualified care for significant distress, restriction, or needs beyond supportive nutrition counselling.", "Offer relevant food-access or practical services when resources are the barrier, and check whether the service is actually accessible."], "reflection": "Choose one routine and name its cue, necessary resources, likely disruption, and backup. Would that backup still work on a difficult day?"}, "sources": [{"label": "AHRQ teach-back", "url": "https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/teachback.html"}, {"label": "NICE behaviour change: individual approaches", "url": "https://www.nice.org.uk/guidance/ph49/chapter/recommendations"}]}, "lesson-17": {"title": "Professional Development", "kicker": "Turn learning into observable, ethical practice improvement • Supplementary learning, not the official chapter or assessment.", "steps": [{"id": "l17-interactive-1", "title": "Separate attendance from improvement", "referenceSection": "l17-2", "teach": ["Professional development is the ongoing work of keeping knowledge, skills, judgment, and conduct fit for the role you actually perform. Reading a new article can help, but development is incomplete if nothing changes in how you assess information, communicate, document, or seek help. Distinguish attendance, learning, and practice improvement. Attendance means being present at an activity.", "Learning means acquiring or revising understanding or a skill. Practice improvement means applying that learning in a way that can be observed or evaluated. A certificate usually establishes attendance or completion, not universal competence. An original example: attending a communication workshop is an activity; recognizing that you interrupt clients is learning; deliberately leaving pauses and obtaining feedback is a practice change."], "type": "sort", "prompt": "Classify the strongest evidence each statement actually provides.", "categories": ["Attendance", "Learning", "Practice improvement"], "items": [{"label": "“I completed a communication webinar.”", "category": 0, "feedback": "Completion documents an activity, not automatically competence or a change in practice."}, {"label": "“I can explain why I interrupt when I rush into advice.”", "category": 1, "feedback": "This shows revised understanding; it does not yet demonstrate a changed interaction."}, {"label": "“In supervised role-plays I paused and invited correction; feedback showed fewer missed priorities.”", "category": 2, "feedback": "This links application with observed feedback rather than relying only on a certificate."}, {"label": "“My portfolio lists ten courses.”", "category": 0, "feedback": "A course list records participation. Add what changed and how you reviewed it."}]}, {"id": "l17-interactive-2", "title": "State a useful boundary", "referenceSection": "l17-3", "teach": ["Before offering a service, identify what your education, experience, supervision, employer policies, and applicable legal requirements permit. A course title or personal interest does not by itself authorize diagnosis, prescribing, psychotherapy, or a regulated professional title.", "Verify uncertain requirements through the relevant official regulator or authority rather than relying on promotional material. The UK HCPC standards require its registrants to work within their knowledge and skills, maintain relevant development, and refer when needs exceed their scope. These are cited as an example of a professional regulatory framework, not as rules automatically applying to every reader."], "type": "choice", "prompt": "A client asks, “Can you tell me the medical cause of this symptom?” Choose your response as a trainee nutrition counsellor.", "options": [{"label": "“This course lets me diagnose anything related to food.”", "feedback": "A course title does not authorize diagnosis or regulated practice. Verify actual qualifications, supervision, and applicable requirements.", "correct": false}, {"label": "“I can support practical eating routines, but cannot determine the medical cause. Let’s identify the appropriate professional for that question.”", "feedback": "This explains the boundary while preserving useful support. Referral is a responsible next step, not an admission that the person should be abandoned.", "correct": true}, {"label": "“Professional standards are identical everywhere, so I already know the legal answer.”", "feedback": "Requirements depend on location, profession, registration, and setting. Illustrative UK standards do not establish Ontario rules or your eligibility to practise.", "correct": false}]}, {"id": "l17-interactive-3", "title": "Find the real learning gap", "referenceSection": "l17-4", "teach": ["“I need to learn more about nutrition” is too broad to guide development. Identify a situation, the decision involved, and the knowledge or skill gap. For example: “How can I explain uncertainty in supplement claims without either endorsing them or dismissing the client's experience?” Separate questions about effectiveness from questions about communication or service delivery.", "A clinical intervention question may need research evidence and qualified interpretation. A communication question may benefit from observed practice and feedback. A documentation question may require your organization's policy, not a research paper. Write what you currently think, why you think it, and what evidence would change your mind."], "type": "explore", "prompt": "Noor gave meal-variety advice while the client repeatedly raised cost. Predict which development activity addresses the gap before opening each panel.", "panels": [{"label": "More facts about food groups", "text": "This may increase knowledge but does not directly address missed priorities. Choose learning based on the decision that went wrong, not the easiest course to find."}, {"label": "Agenda-setting role-play with feedback", "text": "Practise an opening priority question, summarize before advising, and ask an observer where the client’s concern was missed. This targets the communication gap."}, {"label": "A vague promise to “be better”", "text": "This gives no observable change or review. State a focused gap, a safe application, and the evidence that would show improvement."}]}, {"id": "l17-interactive-4", "title": "Look past the impressive headline", "referenceSection": "l17-5", "teach": ["Before using a study, identify its question, design, participants, comparison, outcomes, duration, and limitations. NIH explains that different clinical study designs have different strengths and weaknesses; well-designed randomized trials can help evaluate causal effects, while not every question can be addressed that way. An association is not automatically a cause.", "People choosing a particular food may differ in many other ways. A laboratory mechanism is not proof of a meaningful benefit in everyday life. A change in a biomarker is not necessarily equivalent to feeling better, avoiding disease, or living longer. Look for what was actually measured rather than the outcome suggested by the headline."], "type": "choice", "prompt": "A webinar promises a supplement will “transform energy.” It cites a small biomarker study and offers sales commission. What is the sound next step?", "options": [{"label": "Declare the study false solely because a commission is offered.", "feedback": "A conflict deserves scrutiny and disclosure, but does not by itself prove a claim false. Evaluate the evidence and do not let sales incentives determine advice.", "correct": false}, {"label": "Recommend it because the presenter has a polished slide deck.", "feedback": "Presentation quality and attendance certificates do not establish clinical benefit or suitability for an individual client.", "correct": false}, {"label": "Examine participants, comparison, outcomes, duration, harms, and independent evidence; record uncertainty and seek qualified input where needed.", "feedback": "This checks what was actually measured instead of accepting a broad promise. A biomarker change is not automatically an everyday benefit, and commercial interests deserve attention.", "correct": true}]}, {"id": "l17-interactive-5", "title": "Make records useful and safe", "referenceSection": "l17-8", "teach": ["Documentation should allow an authorized reader to understand what happened, what was agreed, and what needs follow-up. Separate reported information from observations and interpretations. Avoid judgmental labels, unsupported diagnoses, and claims of consent that did not occur.", "HCPC's recordkeeping standards for its registrants emphasize clear, accurate, prompt, and secure records. These are useful principles, while specific retention, access, correction, and disclosure requirements must be checked in the reader's own setting. An original note contrast: “Noncompliant again” gives little actionable information. “Client reports the planned food was unavailable during three shifts; chose to explore a workplace storage option” identifies the problem and decision."], "type": "sort", "prompt": "Decide whether each note or action supports a clear record or needs correction.", "categories": ["Useful documentation", "Needs correction"], "items": [{"label": "“Client reports food unavailable during three shifts; chose to explore storage.”", "category": 0, "feedback": "This separates the report from the decision and describes a practical barrier."}, {"label": "“Noncompliant again.”", "category": 1, "feedback": "A judgmental label omits the circumstances and provides little continuity of care."}, {"label": "Paste a distinctive client story into a personal learning tool after removing the name.", "category": 1, "feedback": "Removing a name may not prevent identification. Use approved systems and proper authorization and safeguards."}, {"label": "Document options discussed separately from the action actually agreed.", "category": 0, "feedback": "This prevents an offered suggestion from being misrepresented as consent."}]}, {"id": "l17-interactive-6", "title": "Respond to an error without hiding it", "referenceSection": "l17-9", "teach": ["Be clear about appointment arrangements, communication channels, response times, fees where relevant, and the limits of your availability. Warmth does not require becoming a friend, exchanging personal favours, or providing unlimited access. Consider how power and trust affect decisions about gifts, social media, or personal relationships.", "If you discover an error, prioritize safety, obtain appropriate guidance, and follow the setting's disclosure and incident procedures. Do not conceal it, fabricate a record, or reassure beyond what is known. Learning from an error includes examining the system that allowed it, not only blaming an individual. Professional development also includes recognizing fatigue, overload, and situations in which you need support."], "type": "choice", "prompt": "You notice an inaccurate note after a supervised session. What is the strongest response?", "options": [{"label": "Silently overwrite it so no one can see the mistake.", "feedback": "Concealment undermines an accurate record. Follow the setting’s correction and incident procedures rather than hiding the original error.", "correct": false}, {"label": "Prioritize any safety issue, seek appropriate guidance, and correct the record through the approved process.", "feedback": "This combines immediate responsibility with transparent learning. Review what allowed the error so the improvement addresses the system as well as your own practice.", "correct": true}, {"label": "Promise the client there could not be any consequence before checking.", "feedback": "Do not reassure beyond what is known. Obtain appropriate guidance and follow applicable disclosure procedures.", "correct": false}]}], "practice": {"takeaway": "What this means for my practice: show what changed, seek feedback, protect information, and verify the limits of your actual role.", "ask": ["What specific decision or skill do I need to improve?", "What evidence would change my current view?", "What observable feedback would show that my practice improved?"], "try": ["Create one identify–learn–apply–review entry with a review date.", "Keep a brief evidence note including population, limitations, date checked, and practice implication.", "Use approved records and supervision; keep identifiable client details out of unsecured learning materials."], "refer": ["Check uncertain scope or regulatory requirements with the relevant official authority and your supervisor.", "Seek qualified clinical input when a question exceeds competence; seek supervision promptly when mistakes or overload threaten safe practice."], "reflection": "Choose one development activity. Replace “I attended” with the gap, safe change, feedback method, review date, and remaining uncertainty. What would count as improvement?"}, "sources": [{"label": "HCPC conduct, performance and ethics", "url": "https://www.hcpc-uk.org/standards/standards-of-conduct-performance-and-ethics/"}, {"label": "NIH understanding clinical studies", "url": "https://www.nih.gov/about-nih/science-health-public-trust/tools/understanding-clinical-studies"}, {"label": "NIA reliable health information", "url": "https://www.nia.nih.gov/health/how-find-reliable-health-information-online"}, {"label": "HCPC continuing professional development", "url": "https://www.hcpc-uk.org/standards/standards-of-continuing-professional-development/"}]}};
